window.SEARCH_DATA=window.SEARCH_DATA||{};window.SEARCH_DATA["search/osaki/2014-001.js"]=[{"id":"50fb168d48fe4e85","year":2014,"faction":"大崎ニューネット","kind":"summary","title":"大崎ニューネット収支報告書(PDFファイル:36.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_newnet.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n平成27年3月31日\n大崎市議会議長\n佐藤\n清隆\n様\n会派等名\n代表者名\n大崎ニ\n会長\n氏家\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n大市議会\n273,31\n9号\n収受","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"50fb168d48fe4e85","year":2014,"faction":"大崎ニューネット","kind":"summary","title":"大崎ニューネット収支報告書(PDFファイル:36.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_newnet.pdf","page":2,"text":"( 別紙 )\n1収入\n政務活動費\n2支出\n平成26年度政務活動費収支報告書\n大崎ニ\n930. 000円\n会派等名\n備\nューネット\n考\n調\n研\n広\n広\n査\n研\n修\n報\n聴\n究\n目\n費\n費\n福岡県大野市・長崎県長崎市・福岡県\n204,552広報紙印刷 . 折込\n東京都内調査視察費\n725,448福岡市の調査視察費\n要請・陳情活動費\n資\n資\n事\n料\n料\n議\n作\n購\n成\n入\n務所\n費\n計\n( 注 ) 備考欄には,主たる支出の内訳を記載する。\n3残額","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"50fb168d48fe4e85","year":2014,"faction":"大崎ニューネット","kind":"summary","title":"大崎ニューネット収支報告書(PDFファイル:36.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_newnet.pdf","page":3,"text":"様式第2号 ( 第4条関係 )\n納\n出\n( 大崎ニ\nーネット )\n支出金額\n差引残高\n840,000\n摘要\n6月25日平成26年度交付金\n平成26年度交付金\n8月7日\n( 佐藤仁一郎分 )\nII 月17日\n調査研究費\n~ 19日\n1月28日\n調査研究費\n~ 29日\n3月16日広報費\n930,000\n470,760\n459,240\n254,688\n204,552\n204,552\n0\nみロ\n930,000","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"3a58c5b7182a14aa","year":2014,"faction":"大崎ニューネット","kind":"activity","title":"大崎ニューネット活動概要報告書(PDFファイル:300KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_newnet.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名   大崎ニューネット\n  視察者名  氏家善男、只野直悦、木村和彦、佐藤弘樹、青沼智雄、佐藤和好、後藤錦信、\n        佐藤仁一郎\n  視 察 日   平成26 年11 月17 日から11 月19 日\n  視 察 先  1．福岡県大野城市 2．長崎県長崎市 3．福岡県福岡市\n         1．都市計画課長 中川裕二氏、係長 花岡氏\n  出 席 者   2．ＮＰＯ「軍艦島を世界遺産にする会」\n         3．総合図書館管理部長 北埼博三氏\n\n\n2. 視察内容\n  視察項目  1．市内循環バスについて（福岡県大野城市）\n         2．世界文化遺産登録に向けて（長崎県長崎市）\n         3．福岡市総合図書館について（福岡県福岡市）\n  視察内容    1． 大野城市における市内循環バスについて\n        ≪導入経過≫\n          平成11 年11 月、市内中心部を担う民間バス路線会社より、慢性的な交通渋滞による\n                 運行時間の乱れ、それに伴う利用者の減少等により、一部路線の廃止の申し出があっ 等により、一部路線の廃止の申し出があっ\n         た。それを受けて、市職員によるバス検討プロジェクトチームを立ち上げ、市内交通シス\n         テムについての資料収集、方向性の模索、バス事業のあり方等を検討した。\n         （１）導入の目的、「誰の、何のためのバスか？」を考える\n        ①交通弱者対策\n          市民が日常生活で多目的（買い物、病院、外出等）に利用できる移動手段を目指す。\n        ②交通空白・不便地域対策\n          バス停から半径300ｍ以上離れた区域をバス空白地域、また運行便数が往復60 便以\n        下の地域を不便地域と位置づけた。そして、それらの地域住民の生活に必要なバス交通\n        を維持・構築し市民の移動の利便性の向上を図る。\n          （２）乗車率の推移（３カ年）\n           平成23 年446,859 人、平成24 年459,071 人、平成25 年460,918 人と緩やかな増加\n         傾向にある。平成25 年の１便あたりの平均乗車人数は約13 人（座席数14 席）である。\n          （３）収益性\n          運賃は利用しやすい100円に設定し乗り継ぎは無料である。保護者同伴未就学児も無\n         料となっている。平成20 年から平成24 年までの平均運行経費は9,265 万4,480 円、運\n           行収入は4,319 万7,200 円である。その金額をもとに、市から運行業者への赤字補填金\n            額は4,945 万7,280 円である。\n          （４）今後の見通し\n         当初の運行協定では、赤字補填方式であったが、運行協定更新にあたり、過去の運\n         行実績をもとに赤字補填額を算定し、定額と定め、補助金として支払うものとした。これに\n        より運行業者の広告収入など自助努力も図られる。\n         （５）コミュニティバスの運行見直しの課題\n         ①コミュニティバスの見直しは、利便性の向上と利用者を増やすことが大前提である。\n         ②コミュニティバスの見直し後も、利用者を増やす努力が必要であり、行政も地域の努力\n          に頼るのみでなく、広報キャンペーンなどを展開し、利用促進に努力する必要がある。\n            ③バス交通協議会で決定された運行がなされ、利用者が減少するなどの状況が発生し するなどの状況が発生し\n          た場合は、速やかに再度運行の見直しを図ることが、協議会の責務である。\n        ※バス交通協議会⇒生活に必要なバス交通の維持と利用者の利便性の向上を目的に、\n         市民公募者・各コミュニティ代表者・市福祉協議会・シニアクラブ連合会・バス会社・学識","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3a58c5b7182a14aa","year":2014,"faction":"大崎ニューネット","kind":"activity","title":"大崎ニューネット活動概要報告書(PDFファイル:300KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_newnet.pdf","page":2,"text":"経験者で構成し、路線バスを含むバス交通全体に関する研究・検討・協議を行う。\n\n\n       2．世界文化遺産登録に向けて\n          軍艦島は、2013 年9 月20 日に世界文化遺産に推薦が決定した「明治日本の産業革\n       命遺産九州・山口と関連地域」の構成遺産の一つとして、また新しい歴史を刻もうとして\n        います。\n          島には2009 年春から上陸できるようになりました。私たちも「さるく号」という船で上陸\n       し、ＮＰＯ法人「軍艦島を世界遺産にする会」の案内で島を視察しました。\n        登録に向けての並々ならぬ活動の情熱が感じられ、今も残る建物の姿や説明を聞き\n       ながら、過ぎ去りし時の流れに思いを馳せ目頭が熱くなりました。\n        大崎市でも世界農業遺産を目指して取り組んでいますが、何よりも市民一人一人が心\n        ひとつにしてゆくことの大切さを痛感しました。\n\n\n       3．福岡市総合図書館について\n       （1）福岡市総合図書館の概要\n        新しい時代のニーズに応えた多彩な機能を持つ生涯学習推進の中枢施設として、図書\n       資料部門、文書資料部門及び映像資料部門の3 部門で構成され、映像ホールやミニシ\n       アターを併設するなど、新しい型の総合図書館であり、収蔵能力200 万冊の規模を誇る\n       図書館として、平成8 年6 月29 日に開館した。\n        （2）施設概要\n       ①所在地：福岡県早良区百道浜三丁目7 番1 号（シーサイドももち地区）\n          ②敷地面積：19,818 ㎡（用地購入費57 億9,400 万円）\n        ③構造：鉄筋コンクリート造・地上5 階建（建築経費113 億8,700 万円）\n          ④延床面積：24,120 ㎡\n         ⑤駐車場：143 台\n         ⑥駐輪場：300 台\n        （3）調査事項\n       ①子ども図書館の運用状況\n         3名で運営。平成25年度末の蔵書は、児童研究資料と児童資料は本館で133,894冊、\n           分館198,750 冊で、合計332,644 冊。団体貸付の児童図書は144,921 冊である。また、平\n         成25 年度の子ども図書館のレファレンスは、窓口相談で10,569 件、電話相談で52 件。\n        利用案内は窓口で7,278 件、電話相談で61 件あった。\n         読書普及活動として、おはなし会（101 回）、こぐまちゃんおはなし会（12 回）、子どもの\n       日特別おはなし会、クリスマスおはなし会、布の絵本講習会、小学生読書リーダー養成\n       講座、夏休み図書館の達人講座など、年間を通して行っている。\n       ②ホール及びビデオライブラリーの利用状況（開館日数288 日）\n        映像資料部門では、映画フィルムなどを後世に継承し、また映像文化の普及・振興及\n       び市民のアジア理解が深まることを目的としている。\n       ・アジア各国及び日本で制作された優れた映画作品のフィルムを収集するとともに、貴重\n       な映像文化財として長期保存すべくフィルムアーカイブを運営する。\n        ・映像ホール・シネマやミニシアターほかで上映・公開している。平成26 年3 月未利用状\n        況は、映像ホール・シネマ入場者数は26,108 人。ミニシアター入場者数は6,942 人。ビデ\n         オ・ＣＤ等貸出数は75,534 点となっている。\n       ③運用の課題と対策\n        開館当時はＶＨＦが最盛期であったが、現在は機材が老朽化している。ＤＶＤに替えて\n       ほしいと言われるが、著作権等での問題があり専門店にまかせている。\n他会派との\n合同実施   ・公明党\n\n                                            以 上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3a58c5b7182a14aa","year":2014,"faction":"大崎ニューネット","kind":"activity","title":"大崎ニューネット活動概要報告書(PDFファイル:300KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_newnet.pdf","page":3,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名   大崎ニューネット\n  視察者名  氏家善男、只野直悦、木村和彦、佐藤弘樹、青沼智雄、佐藤和好、後藤錦信、\n        佐藤仁一郎\n  視 察 日   平成27 年1 月28 日～1 月29 日\n  視 察 先  1．国土交通省都市局（東京都千代田区） 2．ＹＫＫＡＰ㈱本社（東京都千代田区）\n         1．まちづくり企画調整官 大井裕子氏、都市計画課長補佐 大島英司ほか４名\n  出 席 者\n          2．顧問 桑原晴彦氏、総務部長 桑原正和氏\n\n\n2. 視察内容\n  視察項目   1．国土交通省が取り組んでいるまちづくり・住まいづくり\n         2．ＹＫＫＡＰ株式会社の経営理念と事業展開について\n  視察内容   1．国土交通省が取り組んでいるまちづくり・住まいづくり\n          （1）コンパクトシティの推進\n         （2）まちづくりへの民間主体の参画を通じた都市の魅力の向上\n         （3）良好な景観の形成と歴史文化を活かしたまちづくり\n        ≪視察内容≫\n                1-1 都市機能立地支援事業（民間事業者への直接補助）…新規事業\n         都市機能立地支援事業は、公的不動産の有効活用等により、生活に必要な都市機能\n        「誘導施設」を民間事業者が整備する際に、市町村による支援に加え、国が民間事業者\n        に対して直接支援する個別補助事業。なお、市町村が作成する「立地適正化計画」に位\n        置づけた誘導施設で、都市再生整備計画に都市機能立地支援関連事業として、本事業\n         が位置づけられていることが必要。\n         市町村の支援方法について、生活に必要な都市機能「医療・社会福祉・教育文化・商\n        業」を都市機能誘導区域内へ誘導するため、都市機能整備を実施する民間事業者に対\n         し、国から直接支援する（補助率1/2）。「①床・未利用地の活用」、「②複数の敷地の集\n         約・整序」、「③既存ストックの活用」、「④都市機能の複合整備」を行う事業については、\n        交付対象事業費のかさ上げを行い、民間負担を軽減する。都市機能誘導区域の外から\n        中へ誘導施設を移転する場合、土地負担の増分の一部を支援する事業であります。\n                1-2 都市再構築戦略事業（社会資本整備総合交付金）…拡充\n          事業の特徴について、生活に必要な都市機能（医療・社会福祉・教育文化・商業等）を\n        都市機能立地区域内へ誘導するため、社会資本整備総合交付金により整備を支援。交\n         付率をかさ上げして支援（交付率40％⇒50％）。民間事業者が事業主体で間接交付を行\n         う場合「①床・未利用地の活用」、「②複数の敷地の集約・整序」、「③既存ストックの活\n        用」、「④都市機能の複合整備」を行う事業については、交付対象事業費かさ上げを行\n         い、民間負担を軽減する。\n         事業の構成について、（1）中心拠点区域内における誘導施設の整備事業（中心拠点\n         誘導施設（必須）：医療施設、社会施設、教育文化施設、商業施設）。（2）生活拠点区域\n        内における誘導施設の整備事業。（3）中心拠点区域内又生活拠点区域内において、事\n         業を推進するため（1）又は（2）の事業と一体的に実施する都市再生整備計画事業のそ\n         の他の交付対象事業（道路、公園、地域交流センター等）となっている事業でありました。\n        ≪所管≫\n         地域の持続的発展のためにも、コンパクトシティの取り組みは大きな課題であります\n         が、大崎市においては民間活力を取り入れる手法を用いながら、地方創生人口減少スト スト\n        ップに向けて都市の整備開発を積極的に進めていかなければならないと感ずる調査視\n         察でした。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3a58c5b7182a14aa","year":2014,"faction":"大崎ニューネット","kind":"activity","title":"大崎ニューネット活動概要報告書(PDFファイル:300KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_newnet.pdf","page":4,"text":"2．ＹＫＫＡＰ株式会社の経営理念と事業展開について\n        ≪視察内容≫\n         （1）貴社の基本方針「商品力・提案力によるＡＰ事業の持続的成長」の重点施策について\n         （2）建築市場の今後の見通しと貴社事業展開の方向性について\n        ≪視察概要≫\n        日本の新築着工は平成27 年度の政府見通しで89 万2 千戸と報道された。ＹＫＫの見込\n         み戸数90 万戸より厳しい状況であると認識し、４項目の重点政策を掲げ事業拡大に取り\n         組む。\n        ①窓事業の拡大、②リホーム分野の強化、③ビル事業の強化、④エクステリア商品力の\n        強化\n\n\n         ＹＫＫグループの本社ビルを東京神田秋葉原駅前に建設中であり、会社役員、社員の\n        情熱がひしひしと伝わる対応をしていただきました。海外市場向けにも積極的に取り組\n         み、現地の自然に対応した製品の提案など、トップ企業としての気概を強く感じました。\n         東北工場の膝元、大崎市への地域貢献も、視察者一同の思いとして、お願いしてまい\n          りました。\n 他会派との\n  合同実施   ・公明党\n\n                                              以 上\n\n\n         会 派 広 報 広 聴 活 動 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 活動概要\n  会 派 名   大崎ニューネット\n  会 員 名  氏家善男、只野直悦、木村和彦、佐藤弘樹、青沼智雄、佐藤和好、後藤錦信、\n        佐藤仁一郎\n  活動項目   (１)議会報告（広報紙）作成・配布\n\n\n2. 活動内容\n  摘 要   （１）議会報告（広報紙）の作成・配布\n         ① 議会報告（Ｂ４版カラー刷 ２ページ）を40,800 枚作成し配布した。（新聞折り込み）","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"49468b51e8356a60","year":2014,"faction":"改新クラブ","kind":"summary","title":"改新クラブ収支報告書(PDFファイル:34.3KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_kaishin.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n平成27年3月31日\n大崎市議会議長\n佐藤\n清隆\n様\n会派等名\n代表者名\n改新クラブ\n会長門間\n忠\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n大崎市議会\n273.31\n收受","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"49468b51e8356a60","year":2014,"faction":"改新クラブ","kind":"summary","title":"改新クラブ収支報告書(PDFファイル:34.3KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_kaishin.pdf","page":2,"text":"( 別紙 )\n1収入\n政務活動費\n2支出\n平成26年度政務活動費収支報告書\n720. 000円\n金\n会派等名\n備\n改新クラブ\n考\n研\n修\n報\n聴\n究\n目\n費\n費\n額 ( 円 )\n調\n研\n広\n広\n査\n要請,陳情活動費\n資\n資\n事\n料\n料\n議\n作\n購\n成\n入\n務所\n費\n費\n計\n福島県会津若松市,喜多方市\n東京都内調査視察費\n720 OOO 兵庫県養父市 . 京都府舞鶴市 . 綾部市\n720 OOO\n( 注 ) 備考欄には . 主たる支出の内訳を記載する。\n3残額","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"49468b51e8356a60","year":2014,"faction":"改新クラブ","kind":"summary","title":"改新クラブ収支報告書(PDFファイル:34.3KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_kaishin.pdf","page":3,"text":"様式第2号 ( 第4条関係 )\n出\n納\n( 改新クラブ )\n支出金額\n摘要\n6月25日平成26年度交付金\n8月 Ⅱ 日\n調査研究費\n~ 12日\n11月17日\n調査研究費\n~ 19日\n3月12日\n調査研究費\n~ 13日\n127,991\n376,119\n215,890\nニ一口\n合\n720,000","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  改新クラブ\n  視察者名  門間忠、中鉢和三郎、八木吉夫、佐藤清隆、大山巖、氷室勝好\n  視 察 時   平成26 年8 月11 日から8 月12 日\n  視 察 先   1．㈱グリーン発電会津（会津若松市） 2．福島県会津若松市 3．福島県喜多方市\n         1．説明担当者\n  出 席 者\n          3．喜多方市市民部生活環境課主査 査 小林修氏\n\n\n2. 視察内容\n  視察項目  1．㈱グリーン発電会津におけるバイオマス発電事業について\n        2．会津若松市立会津図書館の実態について\n         3．Ｖ－Ｌｏｗマルチメディア放送の取り組みについて\n  視察内容  1．㈱グリーン発電会津におけるバイオマス発電事業について\n           (1)会社概要\n        ①社名 株式会社グリーン発電会津\n        ②設立 平成22 年12 月1 日\n        ③資本金 1 億3,300 万円（平成23 年9 月現在）\n        ④共同出資社 株式会社ノーリン\n        ⑤代表取締役 滝澤 誠\n        ⑥本社 福島県会津若松市河東町工業団地1 番地1\n        ⑦事業内容 発電及び電力の供給、発電所の運営、蒸気・温水その他の熱エネルギー\n        の供給\n           (2)発電事業\n                ①事業実施主体の概要 体の概要\n                                                                                     事業実施主体は、㈱グリーン発電会津ですが、これは本事業を唯一に行う目的で設立 体は、㈱グリーン発電会津ですが、これは本事業を唯一に行う目的で設立\n         された企業です。地元林業会社である㈱ノーリンとグリーン・サーマル㈱の共同出資によ\n         って立地している事業体です。\n          バイオマス集荷業務を㈱ノーリンが担当し、発電所の開発・運営ノウハウをグリーン・\n         サーマル㈱が提供し、各分野のスペシャリストが1 つの企業体となり、発電事業を一体経\n         営することで効率よい企業経営を実現しています。\n        ②事業概要\n         ・総事業費 約25 億円（内、農水省補助金9 億円）、・資本金 9,000 万円\n         ・運転日数 340 日、・稼働時間 24 時間、・送電出力 4,700Ｋｗ\n         ・年間送電量 約40,000ＭＷｈ/年\n         ③原材料（燃料）の集材\n                   会津地方では、間伐と主伐合わせて年間平均 伐合わせて年間平均15 万トン未利用材が発生する。\n         収集・運搬を担当する㈱ノーリンでは、比較的簡単に利用可能な毎年約7 万トンを集材\n         し、チップ化し発電所に供給する。\n         未利用材毎年約7 万トンから求められる発電規模が5ＭＷであり、発電規模を5ＭＷと\n        した理由は、会津地方の林業施設のとの需給バランスを勘案し、持続可能な規模として\n         設置したものである。\n          (3)注目すべき点\n        ①山林未利用材のみを燃料用原料とした5ＭＷ級のバイオマス発電としては全国初\n        ②未利用材のみを燃料とする上で、需給バランスを考量した発電規模設定\n           ③3 交替制の24 時間稼働で、年間340 日稼働\n         ④平成24 年7 月の稼働から約2 年間、安定稼働\n         ⑤国の全量買取り制度（ＦＩＴ）により全量販売","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":2,"text":"⑥以下のような本事業による波及効果\n・雇用の創出：発電所従業員17 人、木質燃料集荷・集材60 人\n・環境負荷低減：ＣＯ２削減17,000 トン\n・派生的効果：成長木伐採による高価木種の育成、幼木植樹によるＣＯ２吸収、間伐材利\n用による林地・林道整備、発酵によるメタンガス減少、治山治水、水源涵養、生態系保 、治山治水、水源涵養、生態系保\n全、森林・産業観光及び森林吸収機能の深化\n(4)課題\n①未利用材毎年約7 万トンの安定確保\n②国の全量買取り制度（ＦＩＴ）終了後の経営\n(5)本市として参考になる取り組み\n 本市も西部を中心に広大な森林が広がり、森林資材の有効活用及び、山林の適正な\n整備による自然災害防止の活動が喫緊の課題となっている。\n 大崎森林組合による小径木の集材⇒チップ燃料化⇒さくらの湯への供給というプロセ\nスが昨年度動き始めたが、まだまだ小さな流れであり、山林未利用材の利活用は緒に就\nいたところである。\n 会津における取り組みの内、参考とすべきところは、㈱ノーリンの35 年間の山林事業\nの実績と経験に基づいた山林未利用材の分布とその賦存量の算出にあると考える。\n 山林未利用材を利活用する上では、比較的簡単に利用可能な山林未利用材の量を算\n出し、その集材コストを計算することが不可欠であり、その計算精度が事業の成否に大き\nく関わることになると考える。従って、㈱ノーリンのような地域を知り抜いた山林事業者の\n存在が重要である事を今回の視察研修において学ぶ事ができた。\n(6)所感\n バイオマス発電は発電効率26％を考えると国の全量買取り制度（ＦＩＴ）の下でのみ成\nり立つのではないかと考える。\n やはり、バイオマスの熱利用については、コジェネのようなエネルギー変換効率がより\n高いシステムが求められると考える。\n 株式会社グリーン発電会津の取り組みは、国の全量買取り制度（ＦＩＴ）の一例として捉\nえ、その集材の手法やコスト内容等、「実証的な価値」という意味で貴重な取り組みでは\nないかと考える。\n\n\n2．会津若松市立会津図書館の実態について\n 平成23 年4 月に生涯学習すべての流れを支援することで会津若松市の人づくり、まち\nづくりに貢献する「生涯の学び舎」を目指す、公民館機能と図書館機能を併せ持つ「生涯\n学習総合センター「愛称：会津稽古堂」が開館しました。\n(1) 施設の概要\n・所在地：福島県会津若松市栄町3 番50 号\n・竣工：平成23 年1 月21 日\n・敷地面積：4,762 平方メートル\n・建築面積：2,512 平方メートル\n・延床面積：9,365 平方メートル\n・建物構造：鉄骨鉄筋コンクリート造 地上3 階、地下１階（中2 階を含む）\n・建築費：30 億583 万2 千円\n(2)目指す図書館像\n①市民の求める資料・情報を提供できる図書館\n②年齢・身体的条件を問わず、だれでもが自由に利用できる図書館\n③時代の変化に対応したサービスを提供できる図書館\n④交通・創造・表現の場となる図書館\n(3)図書館事業内容\n①本館機能：開館日338 日、蔵書冊数249,503 冊、利用者数142,477 人（平成24 年）\n②移動図書館機能：開館日110 日、蔵書冊数25,869 冊、利用者数5,529 人（平成24 年）\n(4)図書館事業の充実\n①図書資料等の充実を図るとともに、貴重資料のデータ化に取り組み、利用者へのサー","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":3,"text":"ビスの向上に努める\n②「会津若松市子ども読書活動推進計画」に基づき、子どもの読書活動を推進する\n③移動図書館の利用者拡大及びサービスの充実を図るとともに、円滑な運行に努める\n(5)図書館の改善策\n 歩行時靴の音が床に反響し、騒音になる改善すべきところです\n 蔵書冊数が年々増加9,365 平方メートルの面積は狭い\n\n\n3．Ｖ－Ｌｏｗマルチメディア放送の取り組みについて\n(1)視察研修の目的\n 本市常襲冠水地帯において防災行政無線の補完が喫緊の課題となっており、喜多\n方・会津地方V-Low マルチメディア放送実証実験の検証・成果から学ばせていただく為。\n(2)喜多方市の取り組み\n■喜多方市の現状\n 喜多方市は、平成18 年1 月4 日、1 市（喜多方市）2 町（塩川町・山都町）2 村（熱塩加\n納村・高郷村）の合併により誕生。\n 一方、防災行政無線については、整備済地区と未整備地区との行政サービスの不均\n衡が発生していた。\n■東日本大震災前の取り組み\n 喜多方市ではこれまで、防災行政無線の統合化（デジタル1 波・アナログ3 波、暫定措\n置）、防災行政無線と連携させた全国瞬時警報システム（J アラート）の整備と段階的/計\n画的に整備を行ってきた。\n■東日本大震災を受けて\n 東日本大震災での経験を踏まえ、防災情報ネットワーク整備基礎調査業務委託を実\n施。しかし、熱塩加納・山都・高郷地区は戸別受信機が全戸配備、旧喜多方・塩川地区\nの世帯は全体の約84％、熱塩加納地区をはじめとする既整備地区のデジタル化などに\nよる課題が浮き彫りに。\n■そんな時\n 地上テレビ放送の完全デジタル化による、空き周波数（90～108MHz・V-Low 帯）を使っ\nた、デジタル波、IPDC 技術、マルチメディア放送の存在（計画）を知る。\n■そこで\n この放送を活用して、防災行政無線の代替として活用できないか着目し平成23 年12\n月に、コミュニティFM（喜多方シティエフエム）と連携、実証実験計画を総務省へ提出。\n■原子力災害避難住民等交流事業費補助金\n（ICT 地域のきずな再生・強化事業）※平成24 年5 月15 日付け交付決定\n防災行政無線の代替として検討していく中で、音声・映像・画像など様々なコンテンツが\n放送により配信できることを、会津若松市を中心に多く避難している大熊町民、大熊町民\nの“きずな”の維持の支援、大熊町復興の促進に役立てることができるのでは、大熊町、\n更には会津若松市と連携し、会津若松市ではICT インフラ網の整備、喜多方市では放送\nインフラ網の整備を行い、きずな維持・再生・強化を目的として事業申請。\n■喜多方・会津地方V-Low 実証実験協議会設置\n１．目的\n 喜多方・会津地方のV-Low マルチメディア放送を活用した平時の地域情報提供、非常\n時の災害放送等の実証実験及び調査研究を行う。\n２．設置時期 平成２４年８月２８日\n■喜多方・会津地方V-Low 実証実験協議会の実験試験局に免許取得\n（予備免許：平成25 年2 月28 日付け、本免許：平成25 年3 月22 日付け）\n－インターネット通信規格を利用した防災情報提供の検証－\n 実証実験の概要\n①防災行政無線の補完としての検証\n②自治体との連携の検証\n③防災情報提供の検証（観光客への情報提供、複数市町村での同時活用等）\n④ビジネスモデルの検証","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":4,"text":"■喜多方・会津地方V-Low 実証実験経過報告会開催（平成25 年7 月9 日）\n実証実験のこれまでの経過報告があり、マルチメディア放送の特徴として、\n①屋内でも明瞭に聞こえ受信端末を持ち運べるという防災行政無線の補完性\n②回線の輻輳に影響されず情報を遅延なく大多数に配信可能という通信の補完性\n③蓄積型放送により聞き逃しや聞き間違いがなく欲しい情報をいつでも取得可能という\n放送の補完性の3 つが報告された。\n(3)本市として参考になる取り組み\n 本市と喜多方市と共通の課題は、非常時の災害・防災情報を市民に如何に早く確実に\n届けるかと言う点である。\n 喜多方市の防災行政無線は、本市と同様、合併前の旧市町村のシステムを継承してお\nりアナログ波とデジタル波が混在し未統合となっている。また、戸別受信機の配備も地区\nによってバラツキがあり本市と同じ課題を抱えている。\n 喜多方市は、防災行政無線の代替機能としてのシステム構築を目指す中で、アナログ\nテレビ放送の終了後、法整備が進みつつある新しい放送V-Low マルチメディア放送に注\n目し実証実験を進めているものである。\n 防災行政無線の代替・補完機能としては、様々考えられる。実際に、先進事例としては\nコミュニティーFM、地域WiMAX など様々な例が挙げられる。\n 喜多方市のV-Low の取り組みは、中でもユニークと言える。この取り組みの注目すべ\nき点は次の点であると考える。\n 第一のポイントは、全く新しいメディアであること。\n 第二のポイントは、比較的安価にシステム構築が可能と言うこと。\n 第三のポイントは、災害時のシステムの堅牢性と考える。\n 「第一のポイントは、全く新しいメディアであること。」は、音声のみならず、画像、映像を\n伝送でき、デジタルの特性を活かし、リアルタイムでの視聴のみならず蓄積し後刻繰り返\nし視聴が可能。また、街中、電車の中、移動中の自動車等にデジタルサイネージとして表\n示可能。\n 「第二のポイントは、比較的安価にシステム構築が可能と言うこと。」は、V-Low マルチ\nメディア放送の特性として、ハードとソフトの分離が為されるため、システム全体を自前で\n整備する必要か無いこと。視聴に必要な受信端末も現在開発中ではあるものの、V-Low\nの普及と共に一般家庭、車載機器、携帯機器として市場に出回ることから、行政措置とし\nて配備しなくとも視聴可能端末数は自然に増加すると考える。また、行政措置として配備\nする場合も、専用LSI の低価格化等により低廉に配備が出来ると考えられる。更に、\nV-Low チューナー内蔵WiFi ルーターとのセットで、スマートフォン、タブレットが容易に受\n信端末となることも重要なポイントと考える。\n 「第三のポイントは、災害時のシステムの堅牢性と考える。」は、V-Low は、新たな商用\n放送であり、専業のしっかりした放送事業者がシステムの運用を行うと共に、法的に耐障\n害性・可用性の基準を定められる見通しであることから、災害時においても「停波」のリス\nクは低いものと考えられる。また、「通信」と異なり「放送」であることから、災害時に「通\n信」に付き物の輻輳が無く、非常時・災害時においても安定的に情報伝達が可能と期待\nできる。\n 以上のV-Low の特徴は、大崎市においても非常に魅力的なものと考える。\n 現在、本市の防災行政無線は、受信側を標準形として屋外拡声子局を想定している。\nそして、難聴地区にのみ戸別受信機を補完システムとして配備することとしている。それ\nは、戸別受信機のコスト高によるものである。しかし、気象災害の発生が危惧される悪天\n候の中や、昨今の高気密高断熱化の進んでいる住宅においては、屋外拡声子局からの\n音声を室内においては聞き取りにくいものとなっており、コスト的な障害が無ければ戸別\n受信機を市内全世帯に配備することが望まれる。\n V-Low は、VHF 帯の電波を利用していることからUHF 帯の地デジの１セグ以上に室内\nにおける受信は有利と考えられ、現在のFM ラジオ放送同様に、室内において手軽に卓\n上受信器やスマホ等で聴取可能と考える。この事は、低廉に防災行政無線の補完システ\nムを構築できることを意味し、大きなメリットと考える。\n(4)所感","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":5,"text":"今回の視察研修以前は、「V-Low」と言う言葉は聞いた事がある程度の認識だった。\n         多分、多くの市民/国民にとっての認知度は、その程度のものと思われる。\n         しかし、今回、実際に実証実験を行っている喜多方市において、その実態と可能性につ\n         いて学び、当初目的とした「大崎市における防災行政無線の補完システム」としての活用\n         に現実性がある事を確認できた。\n          ＩＴ若しくは、通信･放送機器/システムの発達/発展は日進月歩であり、平時のみならず\n         非常時においても活用できる機器/システムは、絶え間なく開発され世の中に出回ってい\n         る。しかし、その使い方/可能性の理解は、一朝一夕にして進むものではなく、様々な実\n         証実験を繰り返し、規格の標準化、関連法規の整備、利便性、信頼性やコストパフォーマ\n         ンス等々の市場評価を経て、一般に流通し活用されるものと考える。よって、「V-Low」に\n        ついては、まだまだ普及するまでに時間が掛かる事と思われるが、将来の重要な情報伝\n         達メディア媒体として、本市においても導入の検討を現時点から進めていく事が求められ\n          る。\n         なぜならば、今回の視察において、技術的な実証が相当程度既に進んでいる事が確認\n          でき、報道によれば、2020 年の東京オリンピック開催をターゲットとしてV-Low の普及が\n         進むとの観測もある。\n          本市の防災行政無線整備事業は、2018 年度まで時間を要す。その2 年後にはV-Low\n         の普及期を迎えることから考えれば、V-Low を利用した防災行政無線の補完システムの\n         検討に時間的な余裕がさほど無いのではないだろうか。\n          本市防災担当部門においては、「V-Low」に対する知見を深め、遅滞無く利活用すべく\n         行動する事を強く求め報告とする。\n 他会派との\n  合同実施   ・無\n\n                                              以 上\n\n            会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  改新クラブ\n  視察者名  門間忠、中鉢和三郎、八木吉夫、佐藤清隆、大山巖、氷室勝好\n  視 察 日   平成26 年11 月17 日から11 月19 日\n  視 察 先  1．兵庫県養父市 2．京都府舞鶴市 3．京都府綾部市\n         1．兵庫県養父市 産業環境部（国家戦略特区担当チーム）リーダー 藤山建人氏、主幹 幹\n  出 席 者  岡和明氏、企画総務部 田村亘氏\n        2．京都府舞鶴市保健福祉部障害福祉課 瀬野勝久氏\n\n\n2. 視察内容\n  視察項目  1．養父市における国家戦略特区による地域活性化の取り組み（兵庫県養父市）\n         2．療育施設と保・幼・小の連携による発達障害児支援の取り組み（京都府舞鶴市）\n         3．住みたくなるまち定住促進条例と定住サポート事業（京都府綾部市）\n  視察内容  1．養父市における国家戦略特区（農業）による地域振興について\n          養父市は平成16 年の合併当時は人口3 万人規模であったが10 年間で約12％人口が\n                                                                                                                                                     減少している。一方、生産年齢人口も平成 している。一方、生産年齢人口も平成12 年の16,871 人に対し、平成22 年では\n                  14,491 人となっており、高齢化率も33.1％と急速に進んでいる。\n         このような状況の中で、養父市は自然や歴史、文化等の地域資源を活かした就業機会\n         創出のための産業づくりをめざし、「農業と観光」を機軸に食品加工等との連携による技\n         術導入、普及を担うことの出来る人材育成を推進し、また従来の枠組みを超えて「連携・","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":6,"text":"融合」した新たな地域産業を創出できる事業者の育成に取り組み、中山間地域における\n日本のモデルをめざしている。\n 政策推進のため平成26 年5 月に「国家戦略特区」の指定を受け、中山間地域において\n民間事業者との連携による農業構造改革をすすめ、耕作放棄地の再生、農産物・食品\nの高付加価値化等の革新的農業を実践し、新たな農業モデルを構築するとしている。\n・国家戦略特別区域の名称「養父市中山間農業改革特区」\n【主な特定事業の内容】 な特定事業の内容】\n＜農業分野＞\n(1)農業委員会と市町村の事務分担に係る特例（農地等効率的利用促進事業）\n(2)農業生産法人に係る農地法等の特例（農業法人経営多角化等促進事業）\n(3)農家レストラン設置に係る特例（地域農畜産物利用促進事業）\n(4)農業への信用保証制度の適用関連事業\n＜歴史的建築物の活用分野＞\n(1)古民家等に係る旅館業法施行規則の特例（歴史的建築物利用宿泊事業）\n 中山間地の養父市において、地域創生の課題として、産業振興策を第一とし、農業の\n国家戦略特区を受け、産業再生、改革へ果敢に取り組んでいることに感銘を覚えた。特\nにヨーロッパで行われているＥＰＬ（ローカルパブリックエンタープライズ、地域公共会社）\n方式により、地域の活性化に取り組む「やぶパートナーズ株式会社」では、直営的事業と\nして農業生産、販売、地域物産販売ショップの運営による棚田米、蛇紋岩米等の都市向\nけ販路の拡大等や公共事業として上下水道維持管理事業、行政業務アウトソーシング\n受託事業等に取り組まれており、地域内循環による地域創生やシルバー人材センターの\n労働時間の規制緩和による高齢者雇用の拡大、空き地農地の賃借、所有による販売指\n向型農業の起業のために農地の流動化権限を農業委員会から市長に移譲するなどの\n取り組みは、画期的なことと感心した。\n\n\n2．舞鶴市における発達等に課題のある子どもの支援策について\n 舞鶴市は、発達障害の子どもの保育所・幼稚園から小学校への連携をどうするかに焦\n点をあて、平成19 年・20 年度には国のモデル事業の指定を受け、「発達障害児等支援\n調査事業」として、発達障害児の具体的な支援策の研究・実施に取り組みがされている。\n そのポイントは「発達」として、文部科学省が2002年に実施した全国実態調査によると、\n知的発達に遅れはないものの学習面や行動面の各領域で著しい困難を示すと担当教師\nが回答した児童生徒の割合は6.3％で、30 人学級では1～2 が在籍している可能性があ\nるとのことである。\n 支援の考え方として、特性を理解し本人の力に寄り添った適切な支援、サポート体制と\nして、主な施設が幼稚園・保育所・小学校・中学校・子育て支援センター・舞鶴こども発達 な施設が幼稚園・保育所・小学校・中学校・子育て支援センター・舞鶴こども発達\n支援施設「さくらんぼ園」・京都府立こども療育センター・京都府中丹東保健所・障害者就\n業生活支援センター等々である。\n 事業は、①乳幼児健康診査の改善による早期発見、②就業前施設や児童デイサービ\nス施設のあり方を議論する早期支援、③成長段階に応じた一貫した支援を行うための\n保、小接続プログラムや支援ファイルの導入といった3 つの視点で取り組みを進めてい\nる。\n なお、今後の取り組みのポイントとして健診や保育所、幼稚園等の就学前については、\n概ね市としての仕組み等が整ってきた。今後の課題は保育や教育の質の向上と学齢期\nの支援とのことである。\n 本市においても発達障害児等支援として早期発見、早期支援、一貫した支援、就学・生\n活支援のより充実を思うに参考に値するものと思料される。\n\n\n3．住みたくなるまち定住促進条例と定住サポート事業について\n①綾部市の人口減少問題対策の考え方について 問題対策の考え方について\n  日本が人口減少に向かい始めた今日、綾 に向かい始めた今日、綾部市においても例外でなく、過疎・高齢化、少\n子化による人口減少が続いています。 が続いています。\n 特に若い子育て世代の転入、転出による社会動態の増減は、今後の綾部市の少子化・ 子化・","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":7,"text":"高齢化に大きな影響を与えることから、社会動態における減  しでも食い止めるた\n         め、子育て世代を中心としたＵＩターン者の定住促進を図ることとした。\n        ②定住交流部定住促進課、水源の里・地域振興課設置の目的及び機能\n        ・あやべ桜ヶ丘団地やあやべ檪の里等への定住促進\n         ・ＮＰＯ法人里山ねっと・あやべを中心とした農村都市交流\n        ・水源の里条例の制定や定住住宅の建設等、集落再生に向けた取り組み\n         ・「農」をテーマにした取り組みによる交流人口やＵＩターン者の確保\n        ・綾部市環境市民会議、上林川を美しくする会等の市民団体や事業所と連携した環境保\n        全活動\n        ・資源循環型社会の実現に向けた取り組み\n        ・公共下水道事業などによる計画的な水洗化区域の拡大\n         ※全体として概ね順調に推移し、一定の成果をあげている。\n        ③綾部市住みたくなるまち定住促進条例の制定経緯、定住促進体制及び具体的事業と\n        予算措置状況\n         ・豊かな自然やものづくりの伝統、温かい人情等、綾部市の特性と資産を受け継ぎ、発展\n             させ、次代につなげる責務がある。しかし、若者の流出や少子高齢化の進行で綾部市の 子高齢化の進行で綾部市の\n                                                                            人口は減少を続けている。このままでは、地域の活力の低下や経済の衰退、さらには歴 を続けている。このままでは、地域の活力の低下や経済の衰退、さらには歴\n         史・文化的行事の継承やコミュニティの維持等が困難になることが予想されます。このた\n           め、交流の拡大と定住促進ＵＩターン者を加えた地域振興を図り、人口減少に歯止めをか に歯止めをか\n         け、持続可能なまちづくりに向けた取り組みを進めていかなければならない。このような\n         認識のもと、ふるさとに誇りと愛情を持ち、住んでよかった、住みたくなるまち綾部の実現\n        をめざし、市、市民等及び事業者が連携、協働する中で一丸となって定住促進に取り組\n         むことを決し、条例を制定した。\n                               ・市民、地域、事業者の主体的かつ積極的な取り組みが促進されるよう必要な支援を行 体的かつ積極的な取り組みが促進されるよう必要な支援を行\n         うため平成26 年度は1,534 万3 千円の予算を計上している。\n         綾部市は少子高齢化の進行で人口が   を続け、このままでは地域の活力の低\n        下や経済の衰退、さらには歴史・文化的行事の継承やコミュニティの維持等が困難にな\n         ることが予想されるため、綾部市では約10 年前から交流の拡大と定住促進、ＵＩターン者\n                      を加えた地域振興を図り、人口減少に歯止めをかけ、持続可能なまちづくりに向けた取 に歯止めをかけ、持続可能なまちづくりに向けた取り\n         組みを進めてきたことに感動し、自分たちの勉強不足が身にしみた。\n\n 他会派との\n  合同実施   ・無\n\n                                              以 上\n\n            会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  改新クラブ\n  視察者名  門間忠、中鉢和三郎、八木吉夫、佐藤清隆、大山巖、氷室勝好\n  視 察 日   平成27 年3 月12 日から3 月13 日\n  視 察 先  1．東京都衆議院第二議員会館 2．東京都台東区 3．楽天株式会社\n        1-1．農林水産省食料産業局輸出促進グループ課長補佐 花田耕介氏、農林水産省食\n        料産業局食品小売りサービス課長補佐 中島勇人氏\n         1-2．内閣府地方創生推進室次長 内閣官房まち・ひと・しごと創生本部事務局次長 内\n  出 席 者  閣審議官 末宗徹朗氏、内閣官房 日本経済再生総合事務局主査 査 竹中理登氏\n         3．楽天株式会社 トラベル事業国内営業部副部長 本田慎一郎氏、トラベル事業国内営\n        業部東日本地域振興グループマネージャー 水口麻季氏、楽天市場事業地域活性化グ\n        ループ 綱川正利氏","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":8,"text":"2. 視察内容\n  視察項目   1-1．農産物の輸出について\n          1-2．地方創生について\n         2．新区長に対する表敬訪問、今後の姉妹都市交流の継続拡大（東京都台東区）\n        3．大崎市の観光行政について、今後の方向性に関する調査\n  視察内容   1-1．農産物輸出の取り組みと平成27 年度農産物輸出の予算概要等について説明を受\n         けた。\n        ①日本の農産物の輸出の現状について\n         輸出の拡大対策のポイントとして、「国別・品目別輸出戦略」の着実な実施に向け、輸\n         出戦略実行委員会を司令塔とし、品目輸出団体や日本貿易振興機構（ＪＥＴＲＯ）を通じ\n        たオールジャパンでの輸出促進体制のもとで国産農産物・食品の輸出増大を図ることが\n         求められている。\n        ②日本の農産物の国際競争力について\n         農林水産省では、日本産農林水産物・食品の輸出に当たり、日本産であることの識別\n        を容易にし、品質やおいしさなど海外の消費者にアピールするため「輸出促進ロゴマー\n          ク」を作成している。\n          農林水産物・食品の輸出額は2012 年においては4,500 億円で2016 年には中間目標と\n             して7,000 億円、さらに2020 年には１兆円をめざしている。\n          一方、世界の食市場規模は2009 年で340 兆円（日本の58 兆円含まず）であり、そのう\n          ち中国・香港・インド・ＡＳＥＡＮ諸国の合計が82 兆円であるが、2020 年の世界の食市場\n         規模は2 倍の680 兆円が推計され、その中にあって中国・インドを含むアジアは約3 倍の\n                229 兆円で日本は58 兆円の1.2 倍の67 兆円を見込んでいる。\n         我が国は自然と共生する「農林水産業」をベースに深遠な知恵と技とが凝縮された日\n        本の「食」と「食文化」等に取り組んでいる。特に、世界の料理界で日本食材の活用推\n         進、日本の「食文化・食産業」の取り組みをＪＥＴＲＯと連携を深めつつ、関係庁・国民各\n         層、関係企業・団体等の理解を得て、官民一体となって取り組むことである。\n           これらのことから、平成27 年度日本食・食文化の魅力発信計画案「日本食魅力アクシ\n          ョンプラン10」に取り組むとのことである。\n        ③現在の大崎市産の農産物の輸出可能性と課題について\n          本市で生産されている期待の新品種「東北194 号」愛称「ささ結び」等及び肉用牛の「仙\n        台牛」などの輸出については、農林水産省の輸出促進関連事業の内容を充分精査し、\n        本市の農産物輸出の実現、一方、学校給食地場食材利用拡大モデル事業については、\n        地域における活動への支援においても導入へ向け担当部局への提言に値する施策であ\n          る。\n         1-2．まち・ひと・しごと総合戦略事業の要点について説明を受け意見交換をした。\n        ①日本の出生数や出生率の推移、将来の人口動向、②地域によって異なる将来人口、\n        人口移動の状況、③首都圏への人口集中の国際比較、東京圏への転入超過、④人口\n        移動と経済指標、⑤都道府県別の出生率と国民希望出生率、⑥経済成長率の将来推\n         計、⑦まち・ひと・しごと創生、⑧地方版総合戦略策定と交付金活用について説明、レク\n         チャーを受けた。\n           今回制定された、まち・ひと・しごと創生法には、初めて日本の人口減少に歯止めをか に歯止めをか\n        けるとともに、東京圏への人口の過度の集中を是正し、それぞれの地域で住みよい環境\n        を確保して、将来にわたって活力ある日本社会を維持していくための総合戦略を計画的\n          に実施していくとあり、国と地方は2019 年度までの5 カ年間の総合戦略を推進していく。\n         基本目標として、地方における安定した雇用の創出、地方への新しい人の流れをつく\n         る、若い世代の結婚、出産、子育ての希望をかなえる、時代にあった地域をつくり、安心\n         なくらしをまもるとともに、地域と地域を連携する。との基本目標が示されている。\n          これらの施策の推進には、総合戦略を踏まえた個別政策として7,225 億円と補正予算\n           で措置した3,257 億円と合せて27 年度に1 兆円、来年度以降も地方の実情に応じたきめ\n        細やかな施策を可能にするなどの観点から、地方創生の取り組みに要する経費につい\n         て、地方財政計画の歳出に１兆円を計上するとしている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"3fbd838bc16d7830","year":2014,"faction":"改新クラブ","kind":"activity","title":"改新クラブ活動概要報告書(PDFファイル:482.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kaishin.pdf","page":9,"text":"地方版総合戦略の策定のポイントは、成果目標、重要業績指標（ＫＰＩ）の設定やＰＤＣＡ\n       サイクルの確立、住民・産官学金言の参画、市町村間の連携などが示されている。とりわ\n               け地方議会においては、地域の人口減少に歯止めをかけ、地域の活力を維持増進し、 に歯止めをかけ、地域の活力を維持増進し、\n       持続可能な地域創生のためのしっかりした議論をお願いしたいとのことであった。\n        意見交換として、省庁の縦割り行政との関連、財政支援のあり方、人的資源の必要性\n       等について話し合いましたが、まち・ひと・しごと創生総合戦略の達成いかんが活力ある\n       日本の最重要課題であることを確認した。\n\n\n       2．台東区新区長に表敬訪問し、今後の姉妹都市交流の継続拡大について懇談をした。\n\n\n       3．大崎市の観光行政について、今後の方向性に関する調査\n        <視察目的>\n       ①大崎市及び鳴子温泉の観光地としての評価\n       ②楽天トラベル観光振興支援事業について\n       ③外国人観光客の東北地方及び大崎市への誘客の可能性と課題\n        ④ニッポンを元気にしようプロジェクト「まち楽」について\n        楽天トラベルの地域振興事業とは、効果的なプロモーション手法により、宿泊施設単体\n       ではなく、エリア全体を活性化させることで、人泊数を拡大させるもの。\n       ※効果的なプロモーション手法とは。\n             (1)Ｗeb 特集やメルマガなどＩＴを活用した地域情報の発信\n       (2)宿泊施設向けの説明会、ユーザー調査など、エリアを巻き込んだ情報の発信\n        (3)終了後の効果検証レポートをもとに、今後のプロモーションへの活用\n       ⇒どれだけ「宿泊客」増ができたかを目標とする。\n           地域活性化グループの主な活動内容 な活動内容\n       ・ネット通販の仕組みの提供にとどまらず、講師派遣によるセミナーの開催等による支援\n        ・全国38 の自治体と業務連携し、地元企業の出店支援、県産品の国内外に向けた情報\n       発信\n       ・うまいもの大会の開催（実際に首都圏等で物産展を開催）\n        ・楽天カフェ、東京渋谷を1 カ月借り切って物産販売、オリジナルメニューの提供\n       ・「まち楽」、自治体との連携協力協定のもと、物産販売、観光誘客拡大を連携し進める\n        楽天（株）を訪問し、楽天市場事業の地域活性支援と楽天トラベル事業の地域振興事\n       業について調査を行った。ともに、楽天の得意とするＥＣをベースに物産や宿泊施設をネ\n       ット上で販売するもので、昨今のネット社会の浸透により注目されている。\n        両方の共通点は、単に個々の品目又は施設を売るのではなく、自治体と連携の上でエ\n       リア全体を活性化し売り上げを効果的にアップさせるものである。\n        また、その対象とする顧客は日本全国であり、容易に域外に顧客を拡げ、域外に対す\n       る売り上げアップの有効な手段と考えられる。従って、市も連携し財政支援をしながら積\n       極的な利用を促進すべきものと考える。\n        地方創生関連事業においても、これまでの取り組みとは別次元への挑戦と位置づけ積\n       極的に楽天（株）などの提供するＥＣ事業を利活用すべきと考える。ＥＣ等のＩＴ活用は時\n       代の要請であり、自治体間競争を勝ち抜くために積極的に利用すべきである。そして、そ\n       のための人材育成も含めた対応が自治体に求められている。\n他会派との\n合同実施   ・無\n\n                                            以 上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"a02bc5a21a3ef6e7","year":2014,"faction":"大志会","kind":"summary","title":"大志会収支報告書(PDFファイル:36.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_taishi.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n平成27年3月31日\n大崎市議会議長\n佐藤\n清隆\n様\n会派等名\n代表者名\n大志会\n会長富田\n文志 ! き\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n大市議会\n273.31\n端,。9幺夛\n収受","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"a02bc5a21a3ef6e7","year":2014,"faction":"大志会","kind":"summary","title":"大志会収支報告書(PDFファイル:36.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_taishi.pdf","page":2,"text":"( 別紙 )\n1収入\n政務活動費\n2支出\n平成26年度政務活動費収支報告書\n会派等名\n600,000円\n士 . △ .\n大,\n考\n研\n修\n報\n聴\n要請・陳情活動費\n議\n作\n購\n究\n成\n入\n目\n費\n費\n金\n額 ( 円 )\n調\n研\n広\n広\n査\n資\n資\n事\n料\n料\n務所\n新潟県佐渡市,富山県黒部市,新潟県\n長岡市調査視察費\n449,296\n143,856会派活動報告チラシ印刷,折り込み\n593,152\n( 注 ) 備考欄には,主たる支出の内訳を記載する。\n3残額\n6. 848円","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"a02bc5a21a3ef6e7","year":2014,"faction":"大志会","kind":"summary","title":"大志会収支報告書(PDFファイル:36.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_taishi.pdf","page":3,"text":"住結住住をーー\n様式第2号 ( 第4条関係 )\n出\n納\n簿\n( 大志会 )\n摘要\n6月25日平成26年度交付金\n8月 Ⅱ 日預金利子\n調査研究費\n2月9日預金利子\n3月27日広報費\n3月31日精算・戻入\n預金利子\n( 市の歳人へ )\n3月31. 日戻入\n支出金額\n差引残高\n600,000\n600,013\n449,296\n150,717\n1-50,734\n143,856\n6,878\n6,432\n446\n30\n416\n0\n416\nニロ\n合\n600,030","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"bf4f818f1a2affe2","year":2014,"faction":"大志会","kind":"activity","title":"大志会活動概要報告書(PDFファイル:243.8KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_taishi.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  大志会\n  視察者名  富田文志、関武徳、相澤久義、相澤孝弘、山村康治\n  視 察 日   平成26 年9 月1 日から9 月3 日\n  視 察 先  1．新潟県佐渡市 2．新潟県黒部市（YKK 黒部事業所） 3．新潟県長岡市\n        1．新潟県佐渡市農林水産課 藤井係長\n  出 席 者    2．YKK 黒部事業所 田原所長、西田総務部長、加藤総務・人事担当課長、勝田総務部\n        顧客管理室長\n\n\n2. 視察内容\n  視察項目   1．ＧＩＡＨＳの取り組みについて、トキの保護と農業施策について（新潟県佐渡市）\n         2．地元企業と行政の連携について（ＹＫＫ黒部事業所）\n         3．市役所新庁舎建設について（新潟県長岡市）\n  視察内容  1．現在大崎市において、世界農業遺産登録認定へ向けて鋭意取り組んでいるが、先進\n        事例の佐渡市の「トキと共生する佐渡の里山」の現状と世界農業遺産への理解と認識を\n         深めるため、研修視察を行った。\n          佐渡市の「トキと共生する佐渡の里山」は、平成23 年に日本で初めて世界農業遺産に\n        登録され、その後の佐渡の農業にどう生かされているのかなどについて、佐渡市役所藤\n         井係長より説明を受け、意見交換をした。その概要を報告いたします。\n        Q．大崎市では、蕪栗沼周辺水田と化女沼がラムサール登録湿地に認定され、当時は市\n        民の関心が高かったが、佐渡での世界農業遺産登録後において、市民の意識をどうみ\n         ているか。\n          A．平成23 年4 月に認定を受け、翌年平成24 年2 月に市民アンケートを行ったが、農家\n        は様々な取り組みの中で生かそうとしているが、一般市民は世界農業遺産登録認定のこ\n         とは知っていてもほとんどが内容については理解していなかったという結果が出ている。\n         Q．国内の認定地域との交流や意見交換会などはどうしているのか。\n         A．全体としては行っていないが、能登とは年1 回行っている。\n         Q．幼小中の教育の場での取り組みはどう進めているのか。\n         A．生き物調査やトキの生態調査をしながら取り組んでいるが地域差があり、なかなか進\n         まない。\n         Q．伝統芸能・文化の継承をどう進めているのか。\n         A．それぞれの地域、集落にある団体と連携しながら取り組んでいるが、年に1,000人ぐら\n         いずつ人口が減少している現状なので大変厳しい状況になっている。\n         Q．「朱鷺と暮らす郷づくり認証制度」の取り組み状況の推移はどうなっているのか。\n         A．ＧＩＡＨＳ認定後においても伸び悩んでいる。制度の見直しをしなければならない。\n         Q．「トキと共生する佐渡の里山」において今後の取り組みは。\n        A．新たな地域の創造を目指し、佐渡棚田協議会の設立・地域おこし協力隊員の積極的\n         な活用・里親制度と新規就農支援による担い手育成を柱に進めていく。\n         以上のような意見交換内容であったことを報告する。\n         なお、世界農業遺産登録認定にあたっては、市民の理解と認知度が肝要であることを\n          強く感じた。\n\n\n           2．平成27 年3 月14 日北陸新幹線の長野～富山・金沢間開業により、黒部宇奈月温泉\n        駅～東京間が2 時間20 分で結ばれ、県民挙げて待ち望んでいる。\n          黒部事業所は、ファスナー、ＡＰ（建材）、工機（ファスナー、建材をつくる器械を自社製\n            造）3 部門があり、国内最大の拠点事業所である。従業員国内外39,000 人、ファスナーを\n         中心に71 カ国108 社、国内17,000 人の従業員のうち12,000 人がＡＰ部門25 事業所で","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"bf4f818f1a2affe2","year":2014,"faction":"大志会","kind":"activity","title":"大志会活動概要報告書(PDFファイル:243.8KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_taishi.pdf","page":2,"text":"事業展開している。\n        工場見学の産業観光化に向けて、富山県石井知事からの依頼でゾーンを整備してＹＫ\n        Ｋツアー（ＹＫＫビル・工場見学）を企画し、平成25 年は年間84,000 人が訪れたという。ま\n        た、黒部市と連携し、1 回30 人規模で年間8 回、ＹＫＫ、黒部峡鉄道（トロッコ電車）、関西\n       電力、ダム、発電所が企業間連携でツアーを企画している。\n        朝の通勤による交通混雑解消については、荻生工場はファスナー、ＡＰ、工機工場があ\n       り、従業員が最も多くいることから、朝社員の時差出勤や近隣に住んでいる地域住民と\n       定期的に話し合いをし、優先順位をつけ道路整備を市に要望し整備されている。また、市\n       や警察等の話し合いで信号等のプログラムをつくり交通混雑解消が図られている。また、\n       工場に放射状に入れるように環境整備が行われている。\n        観光立市を目指す大崎市として産業観光にも目を向け、ＹＫＫＡＰ、一ノ蔵、デリシャスト\n       マト、日帰り温泉施設、道の駅等がコラボした、大崎東部日帰り観光ツアーを企画し、地\n       産の消費拡大を目指し、また、国道4 号の交通渋滞問題解決には新幹線東側の多田川\n       に橋を架ける必要があることを痛感した。\n\n\n       3．新潟県長岡市は平成24 年に市民協働・交流の場として市役所から成るアオーレ長岡\n       を長岡駅前にオープンさせ、長岡の新しい顔となっている。\n        なぜ市役所を駅前にという背景は合併により市職員を総合的に本庁機能強化するため\n       の集約とまちなかの衰退がある。駅前にあった長岡市厚生会館の老朽化に伴い、市役\n       所の建設に踏み出した。同駅前の3 カ所に分庁舎を配置して人々の回遊性も図ってい\n        る。アオーレとは、名称を公募した結果5,500 点位の中から選定されたもので「会いましょ\n       う」を意味する長岡地域の方言で、様々な出会いが生まれるようにという期待が込められ\n        ているとのことでした。\n        設計は建築家の隅研吾氏（最近では歌舞伎座で有名。）による。建築費は本体が131\n       億円余りで駅前に建設するということに関してはマイカー通勤者への駐車場確保問題な\n       どが当初懸念されたが結果として職員の不満はなく、まちなかの回遊性が図られ活性化\n        につながっている。建物は東棟（行政）、西棟（議会、市民活動）、アリーナからなり、その\n       中の中土間は庭のようでもあり、建物中央に挟み込まれるように配置されている。また、\n       木の質感を生かしたデザインが特徴で内装・外装ともに木製のパネルが多用され、温も\n       りが感じられ、壁面や大屋根が強化ガラス張りで建物全体に日差しが入り、それを木製\n       パネルが調光しており、市民が集う、活動拠点としての自遊空間は大変すばらしいもので\n        ある。\n        施設の維持管理について聞いたところ、ガラス清掃は2カ月に1回高所作業車を使用し\n       ている、大屋根の積雪対策に雨水貯留槽から水を流して融雪しているが厳寒期は水量\n       を増やす調整が必要である。このような作業に年間3 億円程度の維持管理費用を拠出\n       するということは当初の予想をはるかに超えるもので、担当職員談として、設計家は積雪\n       地の理解度が不足していたと思う、従って開設後2 年位で一部支障が生じて対応するこ\n        ととなった。\n        最後に長岡市長が本施設を市役所は職員の仕事をする場というより、市民が自由に使\n       う場所と思ってほしいとの意見を強く主張されて推進してきたことに敬意を表したいと感じ\n        た。\n他会派との\n         ・無\n合同実施\n                                            以 上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"bf4f818f1a2affe2","year":2014,"faction":"大志会","kind":"activity","title":"大志会活動概要報告書(PDFファイル:243.8KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_taishi.pdf","page":3,"text":"会 派 広 報 広 聴 活 動 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 活動概要\n  会 派 名  大志会\n  会 員 名  富田文志、関武徳、相澤久義、相澤孝弘、山村康治\n  活動項目   (１)会派活動報告書作成・配布\n\n\n2. 活動内容\n  摘 要   （１）会派活動報告書作成・配布\n            ①会派活動報告書（Ｂ４版１色刷２ページ）18,000 部作成し、新聞折り込みにて配布\n            した。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"216dae8a45811273","year":2014,"faction":"日本共産党大崎市議会議員団","kind":"summary","title":"日本共産党大崎市議会議員団収支報告書(PDFファイル:43.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_kyousan.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n大崎市議会議長\n佐藤\n清隆\n様\n会派等名\n代表者名\n平成27年3月31日\n日本共産党大崎市議会議員団\n団長小沢和悦\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n大崎市議会\n273.31\n羲9女。","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"216dae8a45811273","year":2014,"faction":"日本共産党大崎市議会議員団","kind":"summary","title":"日本共産党大崎市議会議員団収支報告書(PDFファイル:43.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_kyousan.pdf","page":2,"text":"( 別紙 )\n1収入\n政務活動費\n2支出\n平成26年度政務活動費収支報告書\n会派等名日本共産党大崎市議会議員団\n480. OOO 円\n備\n考\n研\n修\n報\n聴\n究\n目\n費\n費\n費\n金\n額 ( 円 )\n調\n研\n広\n広\n査\n要請・陳情活動費\n資\n資\n事\n料\n料\n議\n作\n購\n成\n入\n費\n費\n務所\n印代338.850円\n480.000\n新聞折込料141.150円\n480 OOO\n( 注 ) 備考欄には . 主たる支出の内訳を記載する。\n3残額","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"216dae8a45811273","year":2014,"faction":"日本共産党大崎市議会議員団","kind":"summary","title":"日本共産党大崎市議会議員団収支報告書(PDFファイル:43.2KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_kyousan.pdf","page":3,"text":"様式第2号 ( 第4条関係 )\n6月25日平成26年度交付金\n7月 ll 日議会報告印刷代\n8月18日預金利子\n12月24日議会報告印刷代\n1月5日議会報告新聞折込\n2月16日預金利子\n3月16日議会報告印刷代\n議会報告新聞折込\n3月23日\n料 ( 鳴子 )\n議会報告新聞折込\n3月24日\n料 ( 三本木 )\n議会報告新聞折込料 ( 池月,\n3月26日\n真山,古川,タイムス )\n71,118\n157,962\n480,043\n出\n納\n( 日本共産党大崎市議会議員団 )\n3月27日議会報告印刷代,折込料 ( 岩\n出山一松山一鹿島台,田尻 )\n新聞折込料 ( 松\n3月30日\n預金利子\n3月31日\n( 市の歳入へ )\n支出金額\n43\n070\n7,452\n7,614\n70,000\n13,284\n70,000\n77,500\n差引残高\n480,000\n402,500\n402,512\n332,512\n319,228\n319,259\n249,259\n241,645\n234,193\n163,075\n5,113\n43\n0","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"ab6413b2de324a2e","year":2014,"faction":"日本共産党大崎市議会議員団","kind":"activity","title":"日本共産党大崎市議会議員団活動概要報告書(PDFファイル:171.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kyousan.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  日本共産党大崎市議会議員団\n  視察者名  小沢和悦、鎌内つぎ子、木内知子、遊佐辰雄\n  視 察 日   平成26 年6 月2 日\n  視 察 先  1．宮城県登米市\n  出 席 者\n\n\n2. 視察内容\n  視察項目  1．登米市における公共交通体系について\n  視察内容  １．徹底した市民のための行き届いた低額（または無料）の公共交通体系\n         合併後、路線バスがあいついで撤退。平成17 年10 月、一部の路線バスを市民バスに\n         切り替え「登米市民バス」として試験運行。その後、見直しやダイヤ改正を行い、平成19\n        年から市内全域の市民バスを本格運行。\n         （１）運行している交通手段（市民バス、住民バス、デマンド型乗合タクシー）\n         ①「市民バス」\n                  9 路線（循環路線2 ルート、単線7 ルート）。通学・通勤・通院などで利用できるように近\n         隣の高校や駅まで運行。料金は１回100 円。但し、小学生以下、身障手帳、療育手帳は\n           無料。65 歳以上の免許返納者で無料乗車券提示者は無料（1 年間）\n         ②「住民バス」\n         市民バスのコースから外れている地域を運行。小学校のスクールバス等の空き時間を\n         異活用した住民バスは無料で乗車。運行管理、時刻表は各総合支所が行っている。\n          予算は年間分を教育委員会で契約・支払っている。\n         ※小学校で校外学習などでバスを使うときは市役所・支所で持っている研修用バスを\n          利用\n         ③「デマンド型乗合タクシー」\n         利用登録料 １世帯年間3,000 円。電話予約は利用の30 分前まで。利用料金は登録\n           者300 円、未登録者600 円、子供100 円（小学生未満は無料。親同伴）\n         （２）利用者数と市民の評価\n         ①平成25 年度実績（約40 万人）\n         市民バス 341,881 人（大人266,117 人、子供9,824 人、障害者等65,940 人）\n         住民バス 約50,000 人\n        ②市民の評価と要望\n                  3 年に１回まちづくり市民意識調査を実施。満足度は増加傾向。\n         休日運行の増便、新幹線栗駒高原駅との接続の要望が多い。\n          （３）決算状況（平成25 年度）\n            収入：運賃収入26,611 千円、県補助金3,400 千円程度、特別交付税（運営赤字分の約\n                      8 割が見られる）\n           支出：市民バス運行委託料118,000 千円\n          市からの持ち出し 20,000 千円～30,000 千円（担当職員1 名の給与等は除く）\n         （４）「大崎市との差が、なぜこんなに大きいか」の質問への回答\n         大崎市はＪＲ路線、路線バス、タクシー業者とタクシー台数が登米市よりはるかに多い\n         ので、遠慮して登米市のようにはできないのでしょう、とのこと。\n         財政的には約８割を特別交付税で見てもらえるのに、大崎市はなぜ？という疑問。\n         大崎市は、利便性はだいぶ低いが、理由が業者に遠慮してのことだとしたら間違ってい\n        るように思えてならない。運送業者の協力をいただいて登米市のように行き届いた公共\n         交通を構築することこそ必要なのではないか、と強く感じる視察でした。\n 他会派との\n           ・無\n  合同実施\n                                              以 上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"ab6413b2de324a2e","year":2014,"faction":"日本共産党大崎市議会議員団","kind":"activity","title":"日本共産党大崎市議会議員団活動概要報告書(PDFファイル:171.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_kyousan.pdf","page":2,"text":"会 派 広 報 広 聴 活 動 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 活動概要\n  会 派 名  日本共産党大崎市議会議員団\n  会 員 名  小沢和悦、鎌内つぎ子、木内知子、遊佐辰雄\n  活動項目   (１)議会報告ビラの作成・配布\n\n\n2. 活動内容\n  摘 要   （１）議会報告ビラの作成・配布\n         ① 平成26 年第２回定例会の議会報告ビラ（B４版２色刷 ２ページ）を21,550 枚作成\n            し配布した。\n         ② 平成26 年第３回定例会の議会報告ビラ（B４版２色刷 ２ページ）を20,260 枚作成\n            し配布した。（新聞折り込み）\n         ③ 平成26 年第４回定例会の議会報告ビラ（B４版２色刷 ２ページ）を20,240 枚作成\n            し配布した。\n         ④ 平成27 年第1 回定例会の議会報告ビラ（Ｂ４版２色刷 ２ページ）を35,650 枚作成\n            し配布した。（新聞折り込み）","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"9d86068dc8122d5a","year":2014,"faction":"清和会","kind":"summary","title":"清和会収支報告書(PDFファイル:32.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_seiwa.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n平成27年3月31日\n大崎市議会議長\n佐藤\n清隆\n様\n会派等名\n代表者名\n清和\n会長加藤\n善市\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n2 / 3.3 /","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"9d86068dc8122d5a","year":2014,"faction":"清和会","kind":"summary","title":"清和会収支報告書(PDFファイル:32.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_seiwa.pdf","page":2,"text":"( 別紙 )\n1収入\n政務活動費\n2支出\n平成26年度政務活動費収支報告書\n会派等名\n360. 000円\n円和\n考\n研\n修\n報\n聴\n究\n目\n費\n費\n費\n金\n額 ( 円 )\n調\n研\n広\n広\n査\n要請・陳情活動費\n資\n資\n事\n料\n料\n議\n作\n購\n成\n入\n務所\n費\n費\n計\n富山県南砺市,岐阜県飛市、岐阜県\n高山市 . 岐阜県邯上市の調査視察費\n250.408\n250.408\n( 注 ) 備考欄には,主たる支出の内訳を記載する。\n3残額\n109,592円","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"9d86068dc8122d5a","year":2014,"faction":"清和会","kind":"summary","title":"清和会収支報告書(PDFファイル:32.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_seiwa.pdf","page":3,"text":"様式第2号 ( 第4条関係 )\n出\n納\n( 清和会 )","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"bc0f6426b5c6d9bc","year":2014,"faction":"清和会","kind":"activity","title":"清和会活動概要報告書(PDFファイル:343KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_seiwa.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  清和会\n  視察者名  加藤善市、大友文司、佐藤勝\n  視 察 日   平成26 年10 月27 日から10 月29 日\n  視 察 先  1．富山県南砺市 2．岐阜県飛騨市 3．岐阜県高山市 4．岐阜県郡上市\n          1-1．林政課担当者 1-2 南砺で暮らしません課担当者\n  出 席 者  3．島田政吾議長、橋本正彦議会運営委員長、溝端甚一郎議会運営副委員長\n         4．明宝振興事務所 置田氏、㈱明宝レディース 鷲見氏\n\n\n2. 視察内容\n  視察項目   1-1．有害鳥獣対策について 1-2．定住促進事業について（富山県南砺市）\n         2．国民健康保険事業の運営について（岐阜県飛騨市）\n         3．議会改革の取り組み（岐阜県高山市）\n         4-１．明宝振興事務所における第三セクターの発足と現状（岐阜県郡上市）\n          4-2．特産づくり「明宝トマトケチャップ」の運営と製造現場視察\n         4-3．販売集客施設としての道の駅視察\n  視察内容   1-1．有害鳥獣対策について\n          有害鳥獣の捕獲については、イノシシの捕獲頭数は近年200 頭近くになり、被害額は\n                  1,000 万円～1,500 万円位で箱なわ（50 基）と捕獲隊員50～60 名（免許保持者）で駆除し\n         ている。電気柵の設置延長は20Ｋｍで、年間予算は県補助30 万円、市では約1,150 万\n        円で防止対策協議会や報奨費に充てている。\n         温暖化に伴い、大崎市でもイノシシの被害があるので、被害増の対処が必要と感じ\n          た。\n         1-2．定住促進事業について\n                                                                                                        人口減少に対する定住促進については、南砺で暮らしません課が担当課で本年 に対する定住促進については、南砺で暮らしません課が担当課で本年4 月\n        に組織を見直し、婚活支援、定住対策、空き家対策、山村過疎対策支援等を一元化し\n          た。\n           婚活支援では、おせっかいさん（仲人役）115 名が活動し、出会いの場を創出し、3 年で\n                38 組のカップルを成立させた。（ＮＨＫのテレビ放映）また、出会いイベントに補助金を交\n         付している。\n         定住、空き家対策では、転入、転居に定住奨励金、空き家バンク等に補助金を出し、\n         市に移住・定住を希望する人々には1 口1,000 円で最大1 カ月の体験する住宅も準備し\n         ている。担当課は土日、午後7時まで営業し、5名の職員を配置し、山間過疎地域に条例\n         をつくり支援している。\n          大崎市でも、このきめ細かな施策を20 万都市戦略政策に大いに参考すべきと感じた。\n\n\n        2．国民健康保険事業の運営について\n         飛騨市の国保加入率は約44％で、現年度の収納率は98.54％で県内１位の高い収納\n         率です。納税組合はなく、加入者の９割が口座振替による納付でした。また、未納者には\n        電話や文書あるいは訪問して対話による納付の促進に努めている。\n         医療費の抑制については、第三者行為の疑いのあるレセプトの抽出を行い保健師が個\n         別訪問し、健康管理やコスト意識の高揚など、心理的な対応をしている。\n         少子化対策としては、飛騨市には産婦人科がなく近隣の都市へ依存しているが、不妊\n         治療への治療費助成の条例をつくり、不妊治療対策に取り組んでいる。\n\n\n         3．議会改革の取り組み\n         （１）「議会改革」への取り組みの経緯","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"bc0f6426b5c6d9bc","year":2014,"faction":"清和会","kind":"activity","title":"清和会活動概要報告書(PDFファイル:343KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_seiwa.pdf","page":2,"text":"第1 次議会改革（平成8 年～平成14 年）\n○各会派、事務局から提案された65 件について、市議会議長会の「市議会の活性化方\n策」にしたがって分類し、会派代表者会議、議会運営委員会、議会機能に関する特別委\n員会において、調査・研究\n○主な実施事項\n・一般質問の見直し\n・委員会での一問一答制の導入\n・議員の各種審議会参画の見直し\n・委員会の所管事務調査の活用（閉会中の継続調査を積極的に行うことを合意）\n・請願手続きの緩和など（請願者の押印の廃止(署名の場合のみ)）\n・会議規則、委員会条例の見直し（請願紹介議員への質疑など高山市議会の運営に合\nわせた見直し）\n・情報公開取扱い基準の制定など（インターネット・有線TV 同時中継、録画放送、委員\n会、本会議議事録ネット公開）\n（２）「議会改革等に関する特別委員会」の設置\n○全国各地で議会の在り方が問われている\n○定数・選挙区問題と全国的な議会批判を受け行動開始\n ⇒議会の在り方から議員定数までについて考える「議会改革に関する特別委員会」を\n2009 年12 月、36 人の議員全員で設置、3 つの分科会を設けて運営\n・第1 分科会：「基本理念と議員の活動原則」\n・第2 分科会：「議会機能」\n・第3 分科会：「議員定数と選挙区」\n ⇒「高山市議会のあるべき姿」、「高山市議会の基本理念」を定め、これらに基づいて調\n査研究を推進\n（３）議員定数の決定プロセス\n○議会改革等に関する特別委員会\n 特別委員会を設置後、約3 カ月かけて選挙区・議員定数について検討議論\n○第1 回市民意見交換会の開催\n   2010 年4 月～5 月にかけて市内19 カ所で全市一区定数24 人とする方針について説\n明。市民皆さんから頂いた意見を集約。\n○2010 年6 月定例会\n 次回選挙から全市一区定数24 人とすることを正式に決定\n（４）高山市議会基本条例の制定とその特徴\n   2009 年12 月、「議員全員で構成する議会改革に関する特別委員会」を設置し2011\n年3 月までに38 回の特別委員会(全体会)、89 回の分科会、連絡調整を行うために11 回\nの小委員会を開催し、議会改革について公開で議論するとともに、市民意見交換会など\nの新たな取り組みの施行を重ねてきた。こうした議会改革の集大成として「高山市議会基\n本条例」を、2011 年3 月定例会において全員一致で可決し、同年5 月1 日施行した。\n①実践を通じて策定した条例\n計画～試行～評価～制度化の流れで条例を組み立てた。また、条文の内容を確実に実\n行するために、関連する条例、規程、要綱等を合わせて整備した。\n試行した取り組みは市民意見交換会の開催、事業評価結果の点検、政策討論会の開催\n及び委員会による政策提言の実施などであり、新規に整備した条例、規程、要綱等は12\n本に上る。\n②議論する議会をつくる\nより良い市政づくりには、市民と議会、そして議員同士が積極的に対話し、議論を深める\nことが欠かせないとの認識に基づき、議員同士で行う政策討論会等の実施による議論を\n行う機会を大幅に拡充するとともに、議員間の自由討議、市長等への反問権の付与等に\nよって議論を深めるための手法も充実させた。\n③政策提言によって議会機能を強化～市の政策水準の向上\n○監視型議会を標榜\n 高山市議会では、組織的な政策提言を積極的に行うことを通じて強力な監視型議会を","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"bc0f6426b5c6d9bc","year":2014,"faction":"清和会","kind":"activity","title":"清和会活動概要報告書(PDFファイル:343KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_seiwa.pdf","page":3,"text":"目指すこととした。政策立案に重点を置いた議会活動を展開している議会も見られるが、\n予算編成権が市長に専属すること、執行部に比べ政策立案のためのスタッフが圧倒的\nに手薄であること、また、地域主権の進展等により、執行機関が独自に策定する政策の\n増加が見込まれること等から、現実的選択として政策立案ではなく政策提言を積極的に\n行うこととした。\n○内容の質の向上と高い政治的効果の付与\n・政策提言の内容に高い説得力を持たせるために、作成にあたっては、常任委員会の所\n管事務調査を活用することとし、加えて、常任委員会が市民意見交換会、議員研修会を\n自由に活用できるような仕組みを整えた。また、政策提言の際には、目的・背景・基本的\n方向財政の見通しの4 点を明らかにすることとし、更に、政策提言を行った事項について\nは執行状況をチェックすることを条例に規定し、責任の重さを自覚することとした。3 常任\n委員会ごとに、6～7 件の内財政問題も含めて1 年間議論し、2～3 件に絞り翌年度予算\nに反映させる。\n○議員基礎力の向上\nこの政策提言の取り組みは、行政に対し、政策の提言や立案を求めていくことによって、\n市の政策水準を向上させることを主たる目的としているが、一連の活動を通じて、議員の\n審査能力や調査能力等の基礎力を高めることも重要な目的としている。\n④委員会活動を中心とした政策形成サイクル\n委員会\n○調査研究及び行政との議論。執行部は事業評価シートを提出\n・政策課題を設定し調査研究・政策課題について行政と議論・政策課題について先進地\n視察・政策課題に関する事業の評価結果と予算決算の審査結果の点検・政策課題をテ\nーマに議員研修会・政策提言(案)の作成\n市民意見交換会\n○市民との議論\n・地域別と分野別で政策課題をテーマに議論・次の政策課題の情報収集\n政策討論会\n○議員全員での議論\n・各委員会の政策提言の内容について議員全員で討論・政策提言の合意形成\n ↓\n市長等\n○政策提言を踏まえた政策の改善・立案\n・政策の立案～決定～執行～評価～改善～立案という市の政策形成サイクルにおいて、\n議会は、決定・評価という部分を担っている。決定の前には「審議」、評価の後には改善・\n立案を行政に求める「政策提言」を行う。議会の政策提言は、継続的な業務改善活動を\n推進するマネジメント手法であるPDCA サイクルのAction(改善)を促し、高山市の政策水\n準を向上させる。\n この政策提言は、市政について分野ごとに専門的に調査研究を行う機関である委員会\nを中心に行い、市民意見交換会や議員研修会、政策討論会などの取組を通じて、政策\n提言の妥当性や説得力等を高める。\n⑤市民参加の多様な機会を確保～市民との議論\n○市民意見交換会\n                 議員が少なくなり地域の声が届きにくくなるとの不安に応えるべく、小学校区を単位と なくなり地域の声が届きにくくなるとの不安に応えるべく、小学校区を単位と\nした地域別の市民意見交換会を行うこととした。また、常任委員会の調査研究を深める\nため、各種団体等を対象とした分野別の市民意見交換会も開催することとした。これらの\n意見交換会は、いずれも政策提言に向けた活動の一環として位置づけ、「政策提言」とい\nう形で市民の声を市政に反映させることとした。\n ■地域別市民意見交換会\n  ・年1 回以上20 日以上で実施\n ・各委員会で調査研究中の政策課題を意見交換\n ・政策提言作成の一環\n ■分野別市民意見交換会","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"bc0f6426b5c6d9bc","year":2014,"faction":"清和会","kind":"activity","title":"清和会活動概要報告書(PDFファイル:343KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_seiwa.pdf","page":4,"text":"・各委員会が企画して随時実施\n ・福祉、教育、産業、基盤整備など分野ごとに関係する各種団体等と意見交換\n ・政策提言作成の一環\n○請願及び陳情\n ・陳情等は政策提言作成のための情報源ととらえ、各常任委員会に振り分け調査研究\nに活用している。\n ・請願及び陳情の審議においては、必要に応じて提出者の意見を聞いたうえで審議・審\n査を行うこととしている。\n○情報公開\n 市民との議論の前提となる情報を共有するために、本会議、常任委員会(審査)、予算\n決算特別委員会及び政策討論会をCATV とインターネットで同時及び録画で中継してい\nる。また、委員会と会派の視察報告書、政務調査費の使途等を議会HP で公開している。\nさらに、議長が年5 回程度CATV に出演し、議会の活動状況を報告している。(グローカ\nルの評価で情報公開度No1)\n○議員研修会\n 議員研修会も政策提言に向けた活動の一環として位置づけ、各常任委員会の政策課\n題に関する内容で実施しているが、情報共有という観点からの市民の参加も可とし、講\n師や議員への質疑も認めている。\n⑥議決事件の追加条項を設け、市政に政策立案段階から関与する\n 地方分権の進展、基本構想の策定義務付けの廃止などを受け議会として自治体経営\nの根幹部分に積極的に関与していく必要性を痛感し、議決事件を追加する条項を設ける\nとともに、議決責任を果たすために、市長等に政策立案段階での報告を求めるものとし\nた。現時点では、総合計画の基本計画を位置付けている。\n⑦議員報酬に関する議案は、報酬等審議会の答申に基づくこと\n 議員報酬に関する議案は議員自ら提案していくとする議会も見られるが、当市議会で\nは、自分たちのことを自分たちで提案するのはお手盛りとみられても仕方がないこと、そ\nもそも議員報酬等について諮問を受ける立場にある報酬等審議会を活用することこそが\n基本であると考え、当該議案は、報酬等審議会の答申に基づいて市長が提案することを\n原則とした。なお、議会としても議員報酬の考え方や将来を見据えたあり方等については\n独自に調査研究を重ねることとしている。\n⑧年1 回、基本条例に基づいて議会活動を評価\n 当市議会では、少なくとも年 なくとも年1 回、議会基本条例に基づく活動の評価を、市民の意見も\n聴取しながら議会運営委員会を中心に実施することとした。\n（５）より深い審議・審査の実施～議決責任を果たすために\n 行政課題の複雑多様化や執行部独自に策定する政策の増加を見据え、より深く審議・\n審査することによって議決責任をしっかりと果すべく、議案の審議・審査方法等について\n見直しを図った。\n○事前協議の取止め(審査の形骸化の回避)\n ・委員会協議会を廃止\n ・閉会中の開催する委員会への議案情報の提供は受けない\n ・開会前の議案説明の際には質疑は行わない\n○議会審議と委員会審査の充実\n・質疑と一般質問の分離(目的：議案の内容や論点を明らかにする 質疑を審査に生かす\n委員会の活動期間を拡充する)\n・審査に関する取組の強化(内容：論点整理、現地調査・参考人招致、付帯決議の検討)\n・議員間討議の導入(運用：質疑が多数あり、論点が明確な案件について議長、委員長\nの判断で実施\n○委員会調査の充実\n・常任委員会の任期を1 年から2 年へ\n・閉会中の継続調査を積極的かつ計画的に実施するために、委員会を毎月定例開催と\nした。\n・委員会調査の最終目標を「政策提言」とすることで、活動の統一・シンプル化を図った","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"bc0f6426b5c6d9bc","year":2014,"faction":"清和会","kind":"activity","title":"清和会活動概要報告書(PDFファイル:343KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_seiwa.pdf","page":5,"text":"・委員会の会議運営は、議員間討議を中心に行っている\n○反問\n・行政との論点の活性化を図るべく、市長だけではなく行政側の全ての職員に反問権を\n付与した\n・質問の趣旨確認に止まらず、議会側の提出議案や政策提言に対しても行政側が反問\nできることとした 1 回のみ\n（６）平成25 年度の取り組み 総合計画の策定に向けて\n 平成25 年度から、高山市では、平成27 年度以降のまちづくりの方向性を示す、高山市\n第八次総合計画の策定作業に入った。\n 高山市議会では、条例で高山市総合計画における基本計画を議決事件としていること\nから、平成25 年5 月の臨時議会において、全議員を持って構成する「総合計画に関する\n特別委員会」を設置し、高山市第八次総合計画に関する調査・研究及び審査を行うことと\nした。\n 「総合計画に関する特別委員会」では、平成25 年度、各常任委員会を分科会と位置づ\nけ、分科会ごとに高山市第八次総合計画に向けての政策課題を設定したうえで、その政\n策課題について調査・研究を行ってきた。\n こうした調査・研究の結果を踏まえ、\n  ① 個性ある地域づくりの推進と更なる一体感の確保\n  ② 人口減社会における新たな行財政運営\n  ③ 健康・元気・安心社会の実現\n  ④ 観光まちづくりへの転換\n  ⑤ 都市施設(公共施設)整備の方向性\n  ⑥ 安全で安心して暮らせる社会の実現\n  ⑦ 環境と共生したまちづくり\nの７つを高山市第八次総合計画において取り組むべき政策課題として集約し、10 の政策\n提言として取りまとめ、市長に提案した。\n二元代表制の一翼を担う議事機関としての責務を果たすため、平成26 年度は、今後示\nされる計画案につて、政策提言の繁栄の検証など、審査・議決に向けた取組を進める。\n第八次総合計画に対する政策提言\n①．個性ある地域づくりの推進と更なる一体感の確保\n  政策提言1 地域づくり活動の促進に向けた仕組みづくり\n②．人口減社会における新たな行財政運営\n 政策提言２ 民間の力を活かした行政能力の集約化・効率化\n 政策提言３ 地域の実情に応じた柔軟な行政運営の推進\n 政策提言４ 限られた財源の有効活用と財源の確保\n③．健康・元気・安心社会の実現\n 政策提言５ 高齢者が生き生き暮らせる健康長寿社会の構築\n 政策提言６ 全ての子供が健やかに育つ環境の整備\n④．観光まちづくりへの転換\n 政策提言７ 観光まちづくりへの転換による産業力強化と雇用拡大\n⑤．都市施設(公共施設)整備の方向性\n 政策提言８ 公共施設の適正配置と整備\n⑥．安全で安心して暮らせる社会の実現\n 政策提言９ 災害に強いまちづくり\n⑦．環境と共生したまちづくり\n 政策提言１０ 自然環境を守り、活かすまちづくり\n（７）今後の取り組みについて～議会活動と議員活動の評価\n 第1 段階：議論の広場づくり～基本条例が求める議会と議員の「像」とは？\n 第２段階：相場の形成～議会と議員のあるべき姿\n 第３段階：議会評価制度の構築 政治倫理規程の制定\n(考 察)\n どこの自治体議会も、議会権限の適切な行使は当然のこととしながらも、いかに市民の","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"bc0f6426b5c6d9bc","year":2014,"faction":"清和会","kind":"activity","title":"清和会活動概要報告書(PDFファイル:343KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_seiwa.pdf","page":6,"text":"声を市政に反映させられるか、議会活動がいかに市民目線で行われているか、いかに市\n       民に身近で理解を深めてもらえるか、ということを大きな課題として取り組んでいる。\n       情報公開は当然のことであり、高山市議会が取り組んでいる開かれた議会、行動する議\n       会活動の取り組みに多くの事柄を学んだ。特に、常任委員会活動で政策提言の内容に\n       高い説得力、強力な政治的効果を持たせ、予算編成に反映させる取り組みは大事であ\n       る。市民要望の政策実現に大いに参考となった。\n\n\n       4-１．旧明宝村の職員から郡上市議会議員になっておられる清水議員と置田所長から、\n       熱く旧明宝村時代の村づくりにかけた想いと村民の力を活かして、村づくりに民間の感覚\n       とスピードをもって第三セクターを立ち上げ、特産品開発、温泉資源開発、スキー場開\n       発、道の駅販売施設などの整備を行い、年間150 万人の集客に成功し、小さな村である\n       けれども全国発信出来た誇りを学んだ。\n                                                                                           人口減少対策として都市住民の定住促進策、空き家活用などを中間支援組織のＮＰＯ 対策として都市住民の定住促進策、空き家活用などを中間支援組織のＮＰＯ\n       法人を都市からの移住者を中心に立ち上げ、イベント企画や地域情報誌発行などを積極\n       的に行っている。中でも「月刊めいほう」は、合併後のきめ細かな地域情報が無くなった\n       面を補うなど紙面内容が良い。今後は、現在の無料配布から発行経費問題などから買\n       取配付とするかどうか悩んでいるとの事。\n        4-2．明宝トマトケチャップ製造販売の株式会社明宝レディースを訪問し、3 代目社長であ\n       る鷲見社長から女性だけでの起業の苦労（主婦、母親、妻として事業化）、製品化家庭の\n       拘り（岐阜県産を原材料）、事業成功の要因（村・県の行政支援）、経営努力（販路拡大、\n       商品開発への熱意、他施設での飲食サービス）などの説明を受けた。県内産原材料の\n       確保問題や新商品開発への挑戦などの悩みを抱えつつ前向きな努力に好感が持てる。\n他会派との\n合同実施   ・会派に属さない議員（２人）\n\n                                            以 上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1a3d53f63b931694","year":2014,"faction":"公明党","kind":"summary","title":"公明党収支報告書(PDFファイル:36.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_koumei.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n大崎市議会議長\n佐藤\n清隆\n様\n会派等名\n代表者名\n平成27年3月31日\n公明党\n代表山田和ノ\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n大崎市議会\n273,31\n与端9。\n収受","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"1a3d53f63b931694","year":2014,"faction":"公明党","kind":"summary","title":"公明党収支報告書(PDFファイル:36.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_koumei.pdf","page":2,"text":"( 別紙 )\n平成26年度政務活動費収支報告書\n会派等名\n公明党\n1収入\n政務活動費\n2支出\n科\n目\n調\n査\n研\n究\n修\n研\n広\n報\n費\n広\n聴\n費\n要請,陳情活動費\n議\n費\n資\n料\n作\n成\n資\n料\n購\n入\n事\n務所\n計\n( 注 ) 備考欄には . 主たる支出の内訳を記載する。\n240,000円\n備\n考\n福岡県大野市・長崎県長崎市・福岡\n181362県福岡市の調査視察費117,690円\n東京都調査視察費63,672円\n58.638会派広報誌の印刷代\n3残額\n0円","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"1a3d53f63b931694","year":2014,"faction":"公明党","kind":"summary","title":"公明党収支報告書(PDFファイル:36.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_koumei.pdf","page":3,"text":"様式第2号 ( 第4条関係 )\n出\n納\n( 公明党 )\n差引残高\n摘要\n6月25日平成26年度交付金\n8月18日預金利子\n11月17日\n調査研究費\n~ 19日\n一月28日\n調査研究費\n~ 29日\n2月16日預金利子\n3月17日広報費\n預金利子\n3月26日\n( 市の歳入へ )\n240,000\n240,006\n122,316\n58,644\n58,663\n25\n0\n三ロ\n合","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"52ebab449590cbd6","year":2014,"faction":"公明党","kind":"activity","title":"公明党活動概要報告書(PDFファイル:294.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/3632_01.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  公明党\n  視察者名  山田和明、横山悦子\n  視 察 日   平成26 年11 月17 日から11 月19 日\n  視 察 先  1．福岡県大野城市 2．長崎県長崎市 3．福岡県福岡市\n         1．都市計画課長 中川裕二氏、係長 花岡氏\n  出 席 者   2．ＮＰＯ「軍艦島を世界遺産にする会」\n         3．総合図書館管理部長 北埼博三氏\n\n\n2. 視察内容\n  視察項目  1．市内循環バスについて（福岡県大野城市）\n         2．世界文化遺産登録に向けて（長崎県長崎市）\n         3．福岡市総合図書館について（福岡県福岡市）\n  視察内容    1． 大野城市における市内循環バスについて\n        ≪導入経過≫\n          平成11 年11 月、市内中心部を担う民間バス路線会社より、慢性的な交通渋滞による\n                 運行時間の乱れ、それに伴う利用者の減少等により、一部路線の廃止の申し出があっ 等により、一部路線の廃止の申し出があっ\n         た。それを受けて、市職員によるバス検討プロジェクトチームを立ち上げ、市内交通シス\n         テムについての資料収集、方向性の模索、バス事業のあり方等を検討した。\n         （１）導入の目的、「誰の、何のためのバスか？」を考える\n        ①交通弱者対策\n          市民が日常生活で多目的（買い物、病院、外出等）に利用できる移動手段を目指す。\n        ②交通空白・不便地域対策\n          バス停から半径300ｍ以上離れた区域をバス空白地域、また運行便数が往復60 便以\n        下の地域を不便地域と位置づけた。そして、それらの地域住民の生活に必要なバス交通\n        を維持・構築し市民の移動の利便性の向上を図る。\n          （２）乗車率の推移（３カ年）\n           平成23 年446,859 人、平成24 年459,071 人、平成25 年460,918 人と緩やかな増加\n         傾向にある。平成25 年の１便あたりの平均乗車人数は約13 人（座席数14 席）である。\n          （３）収益性\n          運賃は利用しやすい100円に設定し乗り継ぎは無料である。保護者同伴未就学児も無\n         料となっている。平成20 年から平成24 年までの平均運行経費は9,265 万4,480 円、運\n           行収入は4,319 万7,200 円である。その金額をもとに、市から運行業者への赤字補填金\n            額は4,945 万7,280 円である。\n          （４）今後の見通し\n         当初の運行協定では、赤字補填方式であったが、運行協定更新にあたり、過去の運\n         行実績をもとに赤字補填額を算定し、定額と定め、補助金として支払うものとした。これに\n        より運行業者の広告収入など自助努力も図られる。\n         （５）コミュニティバスの運行見直しの課題\n         ①コミュニティバスの見直しは、利便性の向上と利用者を増やすことが大前提である。\n         ②コミュニティバスの見直し後も、利用者を増やす努力が必要であり、行政も地域の努力\n          に頼るのみでなく、広報キャンペーンなどを展開し、利用促進に努力する必要がある。\n            ③バス交通協議会で決定された運行がなされ、利用者が減少するなどの状況が発生し するなどの状況が発生し\n          た場合は、速やかに再度運行の見直しを図ることが、協議会の責務である。\n        ※バス交通協議会⇒生活に必要なバス交通の維持と利用者の利便性の向上を目的に、\n         市民公募者・各コミュニティ代表者・市福祉協議会・シニアクラブ連合会・バス会社・学識\n         経験者で構成し、路線バスを含むバス交通全体に関する研究・検討・協議を行う。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"52ebab449590cbd6","year":2014,"faction":"公明党","kind":"activity","title":"公明党活動概要報告書(PDFファイル:294.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/3632_01.pdf","page":2,"text":"2．世界文化遺産登録に向けて\n          軍艦島は、2013 年9 月20 日に世界文化遺産に推薦が決定した「明治日本の産業革\n       命遺産九州・山口と関連地域」の構成遺産の一つとして、また新しい歴史を刻もうとして\n        います。\n          島には2009 年春から上陸できるようになりました。私たちも「さるく号」という船で上陸\n       し、ＮＰＯ法人「軍艦島を世界遺産にする会」の案内で島を視察しました。\n        登録に向けての並々ならぬ活動の情熱が感じられ、今も残る建物の姿や説明を聞き\n       ながら、過ぎ去りし時の流れに思いを馳せ目頭が熱くなりました。\n        大崎市でも世界農業遺産を目指して取り組んでいますが、何よりも市民一人一人が心\n        ひとつにしてゆくことの大切さを痛感しました。\n\n\n       3．福岡市総合図書館について\n       （1）福岡市総合図書館の概要\n        新しい時代のニーズに応えた多彩な機能を持つ生涯学習推進の中枢施設として、図書\n       資料部門、文書資料部門及び映像資料部門の3 部門で構成され、映像ホールやミニシ\n       アターを併設するなど、新しい型の総合図書館であり、収蔵能力200 万冊の規模を誇る\n       図書館として、平成8 年6 月29 日に開館した。\n        （2）施設概要\n       ①所在地：福岡県早良区百道浜三丁目7 番1 号（シーサイドももち地区）\n          ②敷地面積：19,818 ㎡（用地購入費57 億9,400 万円）\n        ③構造：鉄筋コンクリート造・地上5 階建（建築経費113 億8,700 万円）\n          ④延床面積：24,120 ㎡\n         ⑤駐車場：143 台\n         ⑥駐輪場：300 台\n        （3）調査事項\n       ①子ども図書館の運用状況\n         3名で運営。平成25年度末の蔵書は、児童研究資料と児童資料は本館で133,894冊、\n           分館198,750 冊で、合計332,644 冊。団体貸付の児童図書は144,921 冊である。また、平\n         成25 年度の子ども図書館のレファレンスは、窓口相談で10,569 件、電話相談で52 件。\n        利用案内は窓口で7,278 件、電話相談で61 件あった。\n         読書普及活動として、おはなし会（101 回）、こぐまちゃんおはなし会（12 回）、子どもの\n       日特別おはなし会、クリスマスおはなし会、布の絵本講習会、小学生読書リーダー養成\n       講座、夏休み図書館の達人講座など、年間を通して行っている。\n       ②ホール及びビデオライブラリーの利用状況（開館日数288 日）\n        映像資料部門では、映画フィルムなどを後世に継承し、また映像文化の普及・振興及\n       び市民のアジア理解が深まることを目的としている。\n       ・アジア各国及び日本で制作された優れた映画作品のフィルムを収集するとともに、貴重\n       な映像文化財として長期保存すべくフィルムアーカイブを運営する。\n        ・映像ホール・シネマやミニシアターほかで上映・公開している。平成26 年3 月未利用状\n        況は、映像ホール・シネマ入場者数は26,108 人。ミニシアター入場者数は6,942 人。ビデ\n         オ・ＣＤ等貸出数は75,534 点となっている。\n       ③運用の課題と対策\n        開館当時はＶＨＦが最盛期であったが、現在は機材が老朽化している。ＤＶＤに替えて\n       ほしいと言われるが、著作権等での問題があり専門店にまかせている。\n他会派との\n合同実施   ・大崎ニューネット\n\n                                            以 上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"52ebab449590cbd6","year":2014,"faction":"公明党","kind":"activity","title":"公明党活動概要報告書(PDFファイル:294.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/3632_01.pdf","page":3,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  公明党\n  視察者名  山田和明、横山悦子\n  視 察 日   平成27 年1 月28 日～1 月29 日\n  視 察 先  1．国土交通省都市局（東京都千代田区） 2．ＹＫＫＡＰ㈱本社（東京都千代田区）\n         1．まちづくり企画調整官 大井裕子氏、都市計画課長補佐 大島英司ほか４名\n  出 席 者\n          2．顧問 桑原晴彦氏、総務部長 桑原正和氏\n\n\n2. 視察内容\n  視察項目   1．国土交通省が取り組んでいるまちづくり・住まいづくり\n         2．ＹＫＫＡＰ株式会社の経営理念と事業展開について\n  視察内容   1．国土交通省が取り組んでいるまちづくり・住まいづくり\n          （1）コンパクトシティの推進\n         （2）まちづくりへの民間主体の参画を通じた都市の魅力の向上\n         （3）良好な景観の形成と歴史文化を活かしたまちづくり\n        ≪視察内容≫\n                1-1 都市機能立地支援事業（民間事業者への直接補助）…新規事業\n         都市機能立地支援事業は、公的不動産の有効活用等により、生活に必要な都市機能\n        「誘導施設」を民間事業者が整備する際に、市町村による支援に加え、国が民間事業者\n        に対して直接支援する個別補助事業。なお、市町村が作成する「立地適正化計画」に位\n        置づけた誘導施設で、都市再生整備計画に都市機能立地支援関連事業として、本事業\n         が位置づけられていることが必要。\n         市町村の支援方法について、生活に必要な都市機能「医療・社会福祉・教育文化・商\n        業」を都市機能誘導区域内へ誘導するため、都市機能整備を実施する民間事業者に対\n         し、国から直接支援する（補助率1/2）。「①床・未利用地の活用」、「②複数の敷地の集\n         約・整序」、「③既存ストックの活用」、「④都市機能の複合整備」を行う事業については、\n        交付対象事業費のかさ上げを行い、民間負担を軽減する。都市機能誘導区域の外から\n        中へ誘導施設を移転する場合、土地負担の増分の一部を支援する事業であります。\n                1-2 都市再構築戦略事業（社会資本整備総合交付金）…拡充\n          事業の特徴について、生活に必要な都市機能（医療・社会福祉・教育文化・商業等）を\n        都市機能立地区域内へ誘導するため、社会資本整備総合交付金により整備を支援。交\n         付率をかさ上げして支援（交付率40％⇒50％）。民間事業者が事業主体で間接交付を行\n         う場合「①床・未利用地の活用」、「②複数の敷地の集約・整序」、「③既存ストックの活\n        用」、「④都市機能の複合整備」を行う事業については、交付対象事業費かさ上げを行\n         い、民間負担を軽減する。\n         事業の構成について、（1）中心拠点区域内における誘導施設の整備事業（中心拠点\n         誘導施設（必須）：医療施設、社会施設、教育文化施設、商業施設）。（2）生活拠点区域\n        内における誘導施設の整備事業。（3）中心拠点区域内又生活拠点区域内において、事\n         業を推進するため（1）又は（2）の事業と一体的に実施する都市再生整備計画事業のそ\n         の他の交付対象事業（道路、公園、地域交流センター等）となっている事業でありました。\n        ≪所管≫\n         地域の持続的発展のためにも、コンパクトシティの取り組みは大きな課題であります\n         が、大崎市においては民間活力を取り入れる手法を用いながら、地方創生人口減少スト スト\n        ップに向けて都市の整備開発を積極的に進めていかなければならないと感ずる調査視\n         察でした。\n\n\n         2．ＹＫＫＡＰ株式会社の経営理念と事業展開について","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"52ebab449590cbd6","year":2014,"faction":"公明党","kind":"activity","title":"公明党活動概要報告書(PDFファイル:294.7KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/3632_01.pdf","page":4,"text":"≪視察内容≫\n         （1）貴社の基本方針「商品力・提案力によるＡＰ事業の持続的成長」の重点施策について\n         （2）建築市場の今後の見通しと貴社事業展開の方向性について\n        ≪視察概要≫\n        日本の新築着工は平成27 年度の政府見通しで89 万2 千戸と報道された。ＹＫＫの見込\n         み戸数90 万戸より厳しい状況であると認識し、４項目の重点政策を掲げ事業拡大に取り\n         組む。\n        ①窓事業の拡大、②リホーム分野の強化、③ビル事業の強化、④エクステリア商品力の\n        強化\n\n\n         ＹＫＫグループの本社ビルを東京神田秋葉原駅前に建設中であり、会社役員、社員の\n        情熱がひしひしと伝わる対応をしていただきました。海外市場向けにも積極的に取り組\n         み、現地の自然に対応した製品の提案など、トップ企業としての気概を強く感じました。\n         東北工場の膝元、大崎市への地域貢献も、視察者一同の思いとして、お願いしてまい\n          りました。\n 他会派との\n  合同実施   ・大崎ニューネット\n\n                                              以 上\n\n\n         会 派 広 報 広 聴 活 動 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 活動概要\n  会 派 名  公明党\n  会 員 名  山田和明、横山悦子\n  活動項目   (１)議会報告書作成・配布\n\n\n2. 活動内容\n  摘 要   （１）議会報告書の作成・配布\n         ① 議会報告書（Ａ４版カラー刷 ２ページ）を2,100 枚作成し配布した。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"c62f2c10983e4461","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"summary","title":"佐藤仁一収支報告書(PDFファイル:34.5KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_satojinichi.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n大崎市議会議長\n佐藤\n清隆\n様\n会派等名\n代表者名\n平成27年3月31日\n会派に属さない議員\n佐藤仁\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n223.37\n/ 安9幺0","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"c62f2c10983e4461","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"summary","title":"佐藤仁一収支報告書(PDFファイル:34.5KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_satojinichi.pdf","page":2,"text":"( 別紙 )\n1収入\n政務活動費\n2支出\n平成26年度政務活動費収支報告書\n会派に属さない議員佐藤仁ー\n120,000円\n額 ( 円 )\n備\n考\n調\n研\n広\n広\n査\n研\n修\n報\n聴\n究\n目\n費\n費\n金\n要請 - 陳情活動費\n資\n資\n事\n料\n料\n議\n作\n購\n成\n入\n務所\n費\n費\n費\n計\n48,000\n72, OOO\n富山県南砺市,岐阜県飛騨市 . 岐阜県\n高山市 . 岐阜県郡上市の調査視察費\n市町村議会議員研修\nまちづくり交通研究所\n120,000\n( 注 ) 備考欄には . 主たる支出の内訳を記載する。\n3残額\n0円","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"c62f2c10983e4461","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"summary","title":"佐藤仁一収支報告書(PDFファイル:34.5KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_satojinichi.pdf","page":3,"text":"様式第2号 ( 第4条関係 )\n出\n納\n( 佐藤仁一 )\n摘要\n6月25日平成26年度交付金\n研修費・調査研究費\n調査研究費\n合","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  会派に属さない議員\n  視察者名  佐藤仁一\n  視 察 日   平成26 年7 月19 日\n  視 察 先  京都まちづくり交通研究所（京都府京都市）\n  出 席 者  宇津克美代表、清水彰事務局長\n\n\n2. 視察内容\n  視察項目                            人口減少並びに交通弱者の定住者と観光交流人口拡大によるまちなか再生などに交通 並びに交通弱者の定住者と観光交流人口拡大によるまちなか再生などに交通\n        問題から取り組んでいる先進事例を調査視察\n  視察内容    京都まちづくり交通研究所は、まちづくりや交通に関する事業を実施することによって、\n        都市の活性化や交通利便性の向上に貢献することを目的として設立した合同会社（ＬＬ\n          Ｃ）です。\n                  2007 年度のＮＥＤＯ（新エネルギー産業技術総合開発機構）事業により都心部の商業\n        者、京都大学、京都市を初めとする民学官が公共交通の利便性向上と利用促進を目的\n         として設立した「交通環境マネジメント委員会」での議論を受けて、地元の商業者が中心\n         となって設立しました。当初は、有限責任事業組合（ＬＬＰ）として発足し、事業の順調な推\n           移を受けて、2009 年より法人格を持つ合同会社に変更しました。\n                  2007 年度には、夜間バス「かわらまち・よるバス」を京都市交通局と連携して運行する\n         とともに、地元の駐輪事業者との連携によって、都心部に位置する「新京極・ろっくんプラ\n         ザ駐輪場」の設置・運営を開始しました。\n          現在、下記の事業を展開し、多くの皆様に利用いただいています。\n         ●かわらまち・よるバス\n          河原町三条・四条河原町と京都駅を結ぶ夜間バス。夜10 時から11 時30 分まで、10\n        分間隔で運行。四条河原町周辺から京都駅への夜の利便性を画期的に向上させまし\n             た。2007 年12 月の運行開始以来、約42 万人に利用いただいています。（2013 年12 月\n         末時点）\n         ●ぎおん・よるバス\n         祇園から四条通を通り、四条烏丸を経由して京都駅へ向かう夜間バス。夜８時から９\n          時30 分まで、10 分間隔で運行。京都駅への帰りの足が不便であった祇園地区などを便\n         利にして、街の活性化を促すために運行を開始。2009 年12 月から運行し、約22 万人を\n          越える利用をいただいています。（2013 年12 月末時点）\n        ●京都観光よるバス\n                                              夜の観光魅力が少ないという京都観光の弱点を補い、より一層の観光振興と京都の ないという京都観光の弱点を補い、より一層の観光振興と京都の\n         魅力の向上のために夜に安価で気軽に京都を周遊できる観光バスとして、2010 年4 月よ\n        り本格運行を開始。日本語のアナウンスのほか、英語・中国・韓国語のアナウンスも行\n         い、外国人旅行客にとっての選択肢の増加にも寄与することを目的としています。これま\n            で約1.5 万人の市民や観光客に利用されています。（2013 年12 月末時点）\n         ●新京極・ろっくんプラザ駐輪場\n         以前は違法駐輪であふれていた新京極六角のろっくんプラザを整備して路上駐輪場を\n            設置し、2008 年１月から運営しています。違法駐輪がなくなり、広場がきれいになるととも\n         に、都心への来訪が便利になっています。運用開始以来、約44 万台の利用をいただい\n            ています。（2013 年12 月末時点）\n        ●京都観光地めぐり時刻表\n         京都の主要な観光地間を移動する際に便利な経路をＷｅｂで検索して、その時刻表を\n        一覧表示できるシステムを京都大学と共同で開発して運用しています。市内の世界遺産\n        や京都駅など観光客の利用が多い20 カ所を結ぶ全ての便の検索が可能です。同システ","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":2,"text":"ムを活用した検索サイトが四条繁栄会商店街振興組合や合同会社ＫＩＣＳにおいて運用\n         されています。\n        ●京都まちなか交通・観光案内所\n         世界の多くの観光都市には、まちなかに観光案内所がありますが、京都の都心部には\n        これまでそういった施設がなかったため、観光客等から大変多くの要望が寄せられてい\n          ました。そのような要望を受けて、2011 年７月から交通と観光の案内所の設置・運営を行\n         っています。すでに21 万人もの来所者がありました。（2013 年12 月末時点）\n         ●京都らくなんエクスプレス\n         京都らくなんエクスプレス“Ｒ′ＥＸ（レックス）は、京都駅と「らくなん進都」へのアクセスが\n          格段に便利になりました。2010 年10 月より京都大学・低炭素都市圏政策ユニットによる\n          社会実験として運行を開始。2011 年10 月には多くの皆さんの声にお応えして一般路線と\n         して運行を開始しました。約53 万人（まち交研移管後）の利用をいただいています。\n                （2013 年12 月末時点）\n        ●京都ひるバス\n        快適な観光バス車両に乗りながら、路線バスのように好きな停留所を選んで自由に乗り\n        降りできる新しい観光周遊バスです。世界遺産６カ所を初めとする京都の主要な観光ス\n         ポットを１時間間隔で結びます。ルートやダイヤもわかりやすく、乗換えの心配もいりませ\n         ん。車内では、次の目的地までの間、京都を紹介するアナウンスも楽しめます。「次の寺\n         社への移動時間を、もっと楽で、楽しいものに」という多くの観光客の方の声にお応えして\n                2013 年4 月より運行したものです。すでに約6,500 人の利用をいただいています。（2013\n           年12 月末時点）\n\n\n          商業者が中心となり京都大学・市との民学官連携。まちづくりと交通問題を連携させな\n        がら、事業化して都市の活性と交通利便性の向上に貢献している。定住者並びに観光客\n         に相乗的な効果を生んでいる。\n 他会派との\n           ・無\n  合同実施\n                                              以 上\n\n            会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  会派に属さない議員\n  視察者名  佐藤仁一\n  視 察 日   平成26 年10 月27 日から10 月29 日\n  視 察 先  1．富山県南砺市 2．岐阜県飛騨市 3．岐阜県高山市 4．岐阜県郡上市\n          1-1．林政課担当者 1-2 南砺で暮らしません課担当者\n  出 席 者  3．島田政吾議長、橋本正彦議会運営委員長、溝端甚一郎議会運営副委員長\n         4．明宝振興事務所 置田氏、㈱明宝レディース 鷲見氏\n\n\n2. 視察内容\n  視察項目   1-1．有害鳥獣対策について 1-2．定住促進事業について（富山県南砺市）\n         2．国民健康保険事業の運営について（岐阜県飛騨市）\n         3．議会改革の取り組み（岐阜県高山市）\n         4-１．明宝振興事務所における第三セクターの発足と現状（岐阜県郡上市）\n          4-2．特産づくり「明宝トマトケチャップ」の運営と製造現場視察\n         4-3．販売集客施設としての道の駅視察\n  視察内容   1-1．有害鳥獣対策について\n          有害鳥獣の捕獲については、イノシシの捕獲頭数は近年200 頭近くになり、被害額は","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":3,"text":"1,000 万円～1,500 万円位で箱なわ（50 基）と捕獲隊員50～60 名（免許保持者）で駆除し\nている。電気柵の設置延長は20Ｋｍで、年間予算は県補助30 万円、市では約1,150 万\n円で防止対策協議会や報奨費に充てている。\n 温暖化に伴い、大崎市でもイノシシの被害があるので、被害増の対処が必要と感じ\nた。\n1-2．定住促進事業について\n            人口減少に対する定住促進については、南砺で暮らしません課が担当課で本年 に対する定住促進については、南砺で暮らしません課が担当課で本年4 月\nに組織を見直し、婚活支援、定住対策、空き家対策、山村過疎対策支援等を一元化し\nた。\n 婚活支援では、おせっかいさん（仲人役）115 名が活動し、出会いの場を創出し、3 年で\n38 組のカップルを成立させた。（ＮＨＫのテレビ放映）また、出会いイベントに補助金を交\n付している。\n 定住、空き家対策では、転入、転居に定住奨励金、空き家バンク等に補助金を出し、\n市に移住・定住を希望する人々には1 口1,000 円で最大1 カ月の体験する住宅も準備し\nている。担当課は土日、午後7時まで営業し、5名の職員を配置し、山間過疎地域に条例\nをつくり支援している。\n 大崎市でも、このきめ細かな施策を20 万都市戦略政策に大いに参考すべきと感じた。\n\n\n2．国民健康保険事業の運営について\n 飛騨市の国保加入率は約44％で、現年度の収納率は98.54％で県内１位の高い収納\n率です。納税組合はなく、加入者の９割が口座振替による納付でした。また、未納者には\n電話や文書あるいは訪問して対話による納付の促進に努めている。\n 医療費の抑制については、第三者行為の疑いのあるレセプトの抽出を行い保健師が個\n別訪問し、健康管理やコスト意識の高揚など、心理的な対応をしている。\n 少子化対策としては、飛騨市には産婦人科がなく近隣の都市へ依存しているが、不妊\n治療への治療費助成の条例をつくり、不妊治療対策に取り組んでいる。\n\n\n3．議会改革の取り組み\n（１）「議会改革」への取り組みの経緯\n第1 次議会改革（平成8 年～平成14 年）\n○各会派、事務局から提案された65 件について、市議会議長会の「市議会の活性化方\n策」にしたがって分類し、会派代表者会議、議会運営委員会、議会機能に関する特別委\n員会において、調査・研究\n○主な実施事項\n・一般質問の見直し\n・委員会での一問一答制の導入\n・議員の各種審議会参画の見直し\n・委員会の所管事務調査の活用（閉会中の継続調査を積極的に行うことを合意）\n・請願手続きの緩和など（請願者の押印の廃止(署名の場合のみ)）\n・会議規則、委員会条例の見直し（請願紹介議員への質疑など高山市議会の運営に合\nわせた見直し）\n・情報公開取扱い基準の制定など（インターネット・有線TV 同時中継、録画放送、委員\n会、本会議議事録ネット公開）\n（２）「議会改革等に関する特別委員会」の設置\n○全国各地で議会の在り方が問われている\n○定数・選挙区問題と全国的な議会批判を受け行動開始\n ⇒議会の在り方から議員定数までについて考える「議会改革に関する特別委員会」を\n2009 年12 月、36 人の議員全員で設置、3 つの分科会を設けて運営\n・第1 分科会：「基本理念と議員の活動原則」\n・第2 分科会：「議会機能」\n・第3 分科会：「議員定数と選挙区」\n ⇒「高山市議会のあるべき姿」、「高山市議会の基本理念」を定め、これらに基づいて調","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":4,"text":"査研究を推進\n（３）議員定数の決定プロセス\n○議会改革等に関する特別委員会\n 特別委員会を設置後、約3 カ月かけて選挙区・議員定数について検討議論\n○第1 回市民意見交換会の開催\n   2010 年4 月～5 月にかけて市内19 カ所で全市一区定数24 人とする方針について説\n明。市民皆さんから頂いた意見を集約。\n○2010 年6 月定例会\n 次回選挙から全市一区定数24 人とすることを正式に決定\n（４）高山市議会基本条例の制定とその特徴\n   2009 年12 月、「議員全員で構成する議会改革に関する特別委員会」を設置し2011\n年3 月までに38 回の特別委員会(全体会)、89 回の分科会、連絡調整を行うために11 回\nの小委員会を開催し、議会改革について公開で議論するとともに、市民意見交換会など\nの新たな取り組みの施行を重ねてきた。こうした議会改革の集大成として「高山市議会基\n本条例」を、2011 年3 月定例会において全員一致で可決し、同年5 月1 日施行した。\n①実践を通じて策定した条例\n計画～試行～評価～制度化の流れで条例を組み立てた。また、条文の内容を確実に実\n行するために、関連する条例、規程、要綱等を合わせて整備した。\n試行した取り組みは市民意見交換会の開催、事業評価結果の点検、政策討論会の開催\n及び委員会による政策提言の実施などであり、新規に整備した条例、規程、要綱等は12\n本に上る。\n②議論する議会をつくる\nより良い市政づくりには、市民と議会、そして議員同士が積極的に対話し、議論を深める\nことが欠かせないとの認識に基づき、議員同士で行う政策討論会等の実施による議論を\n行う機会を大幅に拡充するとともに、議員間の自由討議、市長等への反問権の付与等に\nよって議論を深めるための手法も充実させた。\n③政策提言によって議会機能を強化～市の政策水準の向上\n○監視型議会を標榜\n 高山市議会では、組織的な政策提言を積極的に行うことを通じて強力な監視型議会を\n目指すこととした。政策立案に重点を置いた議会活動を展開している議会も見られるが、\n予算編成権が市長に専属すること、執行部に比べ政策立案のためのスタッフが圧倒的\nに手薄であること、また、地域主権の進展等により、執行機関が独自に策定する政策の\n増加が見込まれること等から、現実的選択として政策立案ではなく政策提言を積極的に\n行うこととした。\n○内容の質の向上と高い政治的効果の付与\n・政策提言の内容に高い説得力を持たせるために、作成にあたっては、常任委員会の所\n管事務調査を活用することとし、加えて、常任委員会が市民意見交換会、議員研修会を\n自由に活用できるような仕組みを整えた。また、政策提言の際には、目的・背景・基本的\n方向財政の見通しの4 点を明らかにすることとし、更に、政策提言を行った事項について\nは執行状況をチェックすることを条例に規定し、責任の重さを自覚することとした。3 常任\n委員会ごとに、6～7 件の内財政問題も含めて1 年間議論し、2～3 件に絞り翌年度予算\nに反映させる。\n○議員基礎力の向上\nこの政策提言の取り組みは、行政に対し、政策の提言や立案を求めていくことによって、\n市の政策水準を向上させることを主たる目的としているが、一連の活動を通じて、議員の\n審査能力や調査能力等の基礎力を高めることも重要な目的としている。\n④委員会活動を中心とした政策形成サイクル\n委員会\n○調査研究及び行政との議論。執行部は事業評価シートを提出\n・政策課題を設定し調査研究・政策課題について行政と議論・政策課題について先進地\n視察・政策課題に関する事業の評価結果と予算決算の審査結果の点検・政策課題をテ\nーマに議員研修会・政策提言(案)の作成","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":5,"text":"市民意見交換会\n○市民との議論\n・地域別と分野別で政策課題をテーマに議論・次の政策課題の情報収集\n政策討論会\n○議員全員での議論\n・各委員会の政策提言の内容について議員全員で討論・政策提言の合意形成\n ↓\n市長等\n○政策提言を踏まえた政策の改善・立案\n・政策の立案～決定～執行～評価～改善～立案という市の政策形成サイクルにおいて、\n議会は、決定・評価という部分を担っている。決定の前には「審議」、評価の後には改善・\n立案を行政に求める「政策提言」を行う。議会の政策提言は、継続的な業務改善活動を\n推進するマネジメント手法であるPDCA サイクルのAction(改善)を促し、高山市の政策水\n準を向上させる。\n この政策提言は、市政について分野ごとに専門的に調査研究を行う機関である委員会\nを中心に行い、市民意見交換会や議員研修会、政策討論会などの取組を通じて、政策\n提言の妥当性や説得力等を高める。\n⑤市民参加の多様な機会を確保～市民との議論\n○市民意見交換会\n                 議員が少なくなり地域の声が届きにくくなるとの不安に応えるべく、小学校区を単位と なくなり地域の声が届きにくくなるとの不安に応えるべく、小学校区を単位と\nした地域別の市民意見交換会を行うこととした。また、常任委員会の調査研究を深める\nため、各種団体等を対象とした分野別の市民意見交換会も開催することとした。これらの\n意見交換会は、いずれも政策提言に向けた活動の一環として位置づけ、「政策提言」とい\nう形で市民の声を市政に反映させることとした。\n ■地域別市民意見交換会\n  ・年1 回以上20 日以上で実施\n ・各委員会で調査研究中の政策課題を意見交換\n ・政策提言作成の一環\n ■分野別市民意見交換会\n ・各委員会が企画して随時実施\n ・福祉、教育、産業、基盤整備など分野ごとに関係する各種団体等と意見交換\n ・政策提言作成の一環\n○請願及び陳情\n ・陳情等は政策提言作成のための情報源ととらえ、各常任委員会に振り分け調査研究\nに活用している。\n ・請願及び陳情の審議においては、必要に応じて提出者の意見を聞いたうえで審議・審\n査を行うこととしている。\n○情報公開\n 市民との議論の前提となる情報を共有するために、本会議、常任委員会(審査)、予算\n決算特別委員会及び政策討論会をCATV とインターネットで同時及び録画で中継してい\nる。また、委員会と会派の視察報告書、政務調査費の使途等を議会HP で公開している。\nさらに、議長が年5 回程度CATV に出演し、議会の活動状況を報告している。(グローカ\nルの評価で情報公開度No1)\n○議員研修会\n 議員研修会も政策提言に向けた活動の一環として位置づけ、各常任委員会の政策課\n題に関する内容で実施しているが、情報共有という観点からの市民の参加も可とし、講\n師や議員への質疑も認めている。\n⑥議決事件の追加条項を設け、市政に政策立案段階から関与する\n 地方分権の進展、基本構想の策定義務付けの廃止などを受け議会として自治体経営\nの根幹部分に積極的に関与していく必要性を痛感し、議決事件を追加する条項を設ける\nとともに、議決責任を果たすために、市長等に政策立案段階での報告を求めるものとし\nた。現時点では、総合計画の基本計画を位置付けている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":6,"text":"⑦議員報酬に関する議案は、報酬等審議会の答申に基づくこと\n 議員報酬に関する議案は議員自ら提案していくとする議会も見られるが、当市議会で\nは、自分たちのことを自分たちで提案するのはお手盛りとみられても仕方がないこと、そ\nもそも議員報酬等について諮問を受ける立場にある報酬等審議会を活用することこそが\n基本であると考え、当該議案は、報酬等審議会の答申に基づいて市長が提案することを\n原則とした。なお、議会としても議員報酬の考え方や将来を見据えたあり方等については\n独自に調査研究を重ねることとしている。\n⑧年1 回、基本条例に基づいて議会活動を評価\n 当市議会では、少なくとも年 なくとも年1 回、議会基本条例に基づく活動の評価を、市民の意見も\n聴取しながら議会運営委員会を中心に実施することとした。\n（５）より深い審議・審査の実施～議決責任を果たすために\n 行政課題の複雑多様化や執行部独自に策定する政策の増加を見据え、より深く審議・\n審査することによって議決責任をしっかりと果すべく、議案の審議・審査方法等について\n見直しを図った。\n○事前協議の取止め(審査の形骸化の回避)\n ・委員会協議会を廃止\n ・閉会中の開催する委員会への議案情報の提供は受けない\n ・開会前の議案説明の際には質疑は行わない\n○議会審議と委員会審査の充実\n・質疑と一般質問の分離(目的：議案の内容や論点を明らかにする 質疑を審査に生かす\n委員会の活動期間を拡充する)\n・審査に関する取組の強化(内容：論点整理、現地調査・参考人招致、付帯決議の検討)\n・議員間討議の導入(運用：質疑が多数あり、論点が明確な案件について議長、委員長\nの判断で実施\n○委員会調査の充実\n・常任委員会の任期を1 年から2 年へ\n・閉会中の継続調査を積極的かつ計画的に実施するために、委員会を毎月定例開催と\nした。\n・委員会調査の最終目標を「政策提言」とすることで、活動の統一・シンプル化を図った\n・委員会の会議運営は、議員間討議を中心に行っている\n○反問\n・行政との論点の活性化を図るべく、市長だけではなく行政側の全ての職員に反問権を\n付与した\n・質問の趣旨確認に止まらず、議会側の提出議案や政策提言に対しても行政側が反問\nできることとした 1 回のみ\n（６）平成25 年度の取り組み 総合計画の策定に向けて\n 平成25 年度から、高山市では、平成27 年度以降のまちづくりの方向性を示す、高山市\n第八次総合計画の策定作業に入った。\n 高山市議会では、条例で高山市総合計画における基本計画を議決事件としていること\nから、平成25 年5 月の臨時議会において、全議員を持って構成する「総合計画に関する\n特別委員会」を設置し、高山市第八次総合計画に関する調査・研究及び審査を行うことと\nした。\n 「総合計画に関する特別委員会」では、平成25 年度、各常任委員会を分科会と位置づ\nけ、分科会ごとに高山市第八次総合計画に向けての政策課題を設定したうえで、その政\n策課題について調査・研究を行ってきた。\n こうした調査・研究の結果を踏まえ、\n  ① 個性ある地域づくりの推進と更なる一体感の確保\n  ② 人口減社会における新たな行財政運営\n  ③ 健康・元気・安心社会の実現\n  ④ 観光まちづくりへの転換\n  ⑤ 都市施設(公共施設)整備の方向性\n  ⑥ 安全で安心して暮らせる社会の実現","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":7,"text":"⑦ 環境と共生したまちづくり\nの７つを高山市第八次総合計画において取り組むべき政策課題として集約し、10 の政策\n提言として取りまとめ、市長に提案した。\n二元代表制の一翼を担う議事機関としての責務を果たすため、平成26 年度は、今後示\nされる計画案につて、政策提言の繁栄の検証など、審査・議決に向けた取組を進める。\n第八次総合計画に対する政策提言\n①．個性ある地域づくりの推進と更なる一体感の確保\n  政策提言1 地域づくり活動の促進に向けた仕組みづくり\n②．人口減社会における新たな行財政運営\n 政策提言２ 民間の力を活かした行政能力の集約化・効率化\n 政策提言３ 地域の実情に応じた柔軟な行政運営の推進\n 政策提言４ 限られた財源の有効活用と財源の確保\n③．健康・元気・安心社会の実現\n 政策提言５ 高齢者が生き生き暮らせる健康長寿社会の構築\n 政策提言６ 全ての子供が健やかに育つ環境の整備\n④．観光まちづくりへの転換\n 政策提言７ 観光まちづくりへの転換による産業力強化と雇用拡大\n⑤．都市施設(公共施設)整備の方向性\n 政策提言８ 公共施設の適正配置と整備\n⑥．安全で安心して暮らせる社会の実現\n 政策提言９ 災害に強いまちづくり\n⑦．環境と共生したまちづくり\n 政策提言１０ 自然環境を守り、活かすまちづくり\n（７）今後の取り組みについて～議会活動と議員活動の評価\n 第1 段階：議論の広場づくり～基本条例が求める議会と議員の「像」とは？\n 第２段階：相場の形成～議会と議員のあるべき姿\n 第３段階：議会評価制度の構築 政治倫理規程の制定\n(考 察)\n どこの自治体議会も、議会権限の適切な行使は当然のこととしながらも、いかに市民の\n声を市政に反映させられるか、議会活動がいかに市民目線で行われているか、いかに市\n民に身近で理解を深めてもらえるか、ということを大きな課題として取り組んでいる。\n情報公開は当然のことであり、高山市議会が取り組んでいる開かれた議会、行動する議\n会活動の取り組みに多くの事柄を学んだ。特に、常任委員会活動で政策提言の内容に\n高い説得力、強力な政治的効果を持たせ、予算編成に反映させる取り組みは大事であ\nる。市民要望の政策実現に大いに参考となった。\n\n\n4-１．旧明宝村の職員から郡上市議会議員になっておられる清水議員と置田所長から、\n熱く旧明宝村時代の村づくりにかけた想いと村民の力を活かして、村づくりに民間の感覚\nとスピードをもって第三セクターを立ち上げ、特産品開発、温泉資源開発、スキー場開\n発、道の駅販売施設などの整備を行い、年間150 万人の集客に成功し、小さな村である\nけれども全国発信出来た誇りを学んだ。\n        人口減少対策として都市住民の定住促進策、空き家活用などを中間支援組織のＮＰＯ 対策として都市住民の定住促進策、空き家活用などを中間支援組織のＮＰＯ\n法人を都市からの移住者を中心に立ち上げ、イベント企画や地域情報誌発行などを積極\n的に行っている。中でも「月刊めいほう」は、合併後のきめ細かな地域情報が無くなった\n面を補うなど紙面内容が良い。今後は、現在の無料配布から発行経費問題などから買\n取配付とするかどうか悩んでいるとの事。\n4-2．明宝トマトケチャップ製造販売の株式会社明宝レディースを訪問し、3 代目社長であ\nる鷲見社長から女性だけでの起業の苦労（主婦、母親、妻として事業化）、製品化家庭の\n拘り（岐阜県産を原材料）、事業成功の要因（村・県の行政支援）、経営努力（販路拡大、\n商品開発への熱意、他施設での飲食サービス）などの説明を受けた。県内産原材料の\n確保問題や新商品開発への挑戦などの悩みを抱えつつ前向きな努力に好感が持てる。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"1631187864a727ea","year":2014,"faction":"会派に属さない議員 佐藤仁一","kind":"activity","title":"佐藤仁一活動概要報告書(PDFファイル:418.4KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_satojinichi1.pdf","page":8,"text":"他会派との\n  合同実施   ・清和会 ・会派に属さない議員\n\n                                              以 上\n\n\n            会 派 研 修 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 研修概要\n  会 派 名  会派に属さない議員\n  参加者名  佐藤仁一\n  研 修 日   平成26 年7 月16 日～7 月18 日\n  研 修 先  1．全国市町村国際文化研修所（滋賀県大津市）\n  講 師 等  関西学院大学専門職大学院経営戦略研究科教授 稲沢克祐氏\n\n\n2. 研修内容\n  研修項目   平成26 年度市町村議会議員研修（３日間コース）\n        自治体決算の基本と実践～行政評価を活用した決算審査～\n  研修内容   第1 部 自治体決算の基礎\n         第2 部 公会計制度改革の理解\n         第3 部 行政評価\n\n\n          稲沢教授から、１日目４時間、２日目５時間の全体講義を受けました。それぞれの全体\n          講義を受けて、10 班に分かれて実践討議を行いました。\n          その内容は、演習１として1 日目に２時間「基礎データと事業の問題点の関連整理」を\n         行い、２日目にも２時間、演習２として「改善案の検討」を行いました。３日目は演習３とし\n         て、午前中「行政評価を利用した決算審査」討議を行い、午後から全体発表を行い、講評\n         を受けました。\n         講義内容はボリュウムがあり時間が不足的であった。先進的な事例を資料として、講\n        義⇒討議⇒実践の研修方法を用いて、理解しやすい実践的な講義であった。\n         稲沢教授が東北大学教育学研究科出身であり、宮城県内の地域理解や私の恩師で\n        ある塚本哲人教授の教え子であったため親近感を持って精力的に研修を受講できた。\n\n\n 他会派との\n           ・無\n  合同実施\n                                              以 上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"52d54e2e38c0bb25","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"summary","title":"豊嶋正人収支報告書(PDFファイル:33.9KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_toyoshima.pdf","page":1,"text":"様式第5号 ( 第3条関係 )\n大崎市議会議長\n佐藤\n清隆\n会派等名\n代表者名\n平成27年3月31日\n会派に属さない議員\n豊嶋正人\n平成26年度政務活動費収支報告について\n紙のとおり政務活動費収支報告書を提出します。\n大崎市議会政務活動費の交付に関する条例第8条の規定に基づき,\n別\n273.37\n- ノ女タ女0","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"52d54e2e38c0bb25","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"summary","title":"豊嶋正人収支報告書(PDFファイル:33.9KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_toyoshima.pdf","page":2,"text":"( 別紙 )\n1収入\n政務活動費\n2支出\n平成26年度政務活動費収支報告書\n会派に属さない議員豊嶋正人\n120. OOO 円\n額 ( 円 )\n備\n考\n調\n研\n広\n広\n査\n研\n修\n報\n聴\n九\n目\n費\n費\n費\n金\n要請 - 陳情活動費\n資\n資\n事\n料\n料\n議\n作\n購\n成\n入\n務所\n費\n計\n富山県南砺市 . 岐阜県飛市 . 岐阜県\n83469\n高山市 . 岐阜県郡上市の調査視察費\n83,469\n( 注 ) 備考欄には,主たる支出の内訳を記載する。\n3残額\n36. 531円","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"52d54e2e38c0bb25","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"summary","title":"豊嶋正人収支報告書(PDFファイル:33.9KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_toyoshima.pdf","page":3,"text":"当を - ま -\n様式第2号 ( 第4条関係 )\n出\n納\n( 豊嶋正人 )\n3月26日精算・戻入","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"15173fd400b3040f","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"activity","title":"豊嶋正人活動概要報告書(PDFファイル:342KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_toyoshima.pdf","page":1,"text":"会 派 視 察 報 告 書\n\n\n                                  大崎市議会 政務活動概要報告書\n                                          平成２７年 ３月３１日 提出\n1. 視察概要\n  会 派 名  会派に属さない議員\n  視察者名  豊嶋正人\n  視 察 日   平成26 年10 月27 日から10 月29 日\n  視 察 先  1．富山県南砺市 2．岐阜県飛騨市 3．岐阜県高山市 4．岐阜県郡上市\n          1-1．林政課担当者 1-2 南砺で暮らしません課担当者\n  出 席 者  3．島田政吾議長、橋本正彦議会運営委員長、溝端甚一郎議会運営副委員長\n         4．明宝振興事務所 置田氏、㈱明宝レディース 鷲見氏\n\n\n2. 視察内容\n  視察項目   1-1．有害鳥獣対策について 1-2．定住促進事業について（富山県南砺市）\n         2．国民健康保険事業の運営について（岐阜県飛騨市）\n         3．議会改革の取り組み（岐阜県高山市）\n         4-１．明宝振興事務所における第三セクターの発足と現状（岐阜県郡上市）\n          4-2．特産づくり「明宝トマトケチャップ」の運営と製造現場視察\n         4-3．販売集客施設としての道の駅視察\n  視察内容   1-1．有害鳥獣対策について\n          有害鳥獣の捕獲については、イノシシの捕獲頭数は近年200 頭近くになり、被害額は\n                  1,000 万円～1,500 万円位で箱なわ（50 基）と捕獲隊員50～60 名（免許保持者）で駆除し\n         ている。電気柵の設置延長は20Ｋｍで、年間予算は県補助30 万円、市では約1,150 万\n        円で防止対策協議会や報奨費に充てている。\n         温暖化に伴い、大崎市でもイノシシの被害があるので、被害増の対処が必要と感じ\n          た。\n         1-2．定住促進事業について\n                                                                                                        人口減少に対する定住促進については、南砺で暮らしません課が担当課で本年 に対する定住促進については、南砺で暮らしません課が担当課で本年4 月\n        に組織を見直し、婚活支援、定住対策、空き家対策、山村過疎対策支援等を一元化し\n          た。\n           婚活支援では、おせっかいさん（仲人役）115 名が活動し、出会いの場を創出し、3 年で\n                38 組のカップルを成立させた。（ＮＨＫのテレビ放映）また、出会いイベントに補助金を交\n         付している。\n         定住、空き家対策では、転入、転居に定住奨励金、空き家バンク等に補助金を出し、\n         市に移住・定住を希望する人々には1 口1,000 円で最大1 カ月の体験する住宅も準備し\n         ている。担当課は土日、午後7時まで営業し、5名の職員を配置し、山間過疎地域に条例\n         をつくり支援している。\n          大崎市でも、このきめ細かな施策を20 万都市戦略政策に大いに参考すべきと感じた。\n\n\n        2．国民健康保険事業の運営について\n         飛騨市の国保加入率は約44％で、現年度の収納率は98.54％で県内１位の高い収納\n         率です。納税組合はなく、加入者の９割が口座振替による納付でした。また、未納者には\n        電話や文書あるいは訪問して対話による納付の促進に努めている。\n         医療費の抑制については、第三者行為の疑いのあるレセプトの抽出を行い保健師が個\n         別訪問し、健康管理やコスト意識の高揚など、心理的な対応をしている。\n         少子化対策としては、飛騨市には産婦人科がなく近隣の都市へ依存しているが、不妊\n         治療への治療費助成の条例をつくり、不妊治療対策に取り組んでいる。\n\n\n         3．議会改革の取り組み\n         （１）「議会改革」への取り組みの経緯","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"15173fd400b3040f","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"activity","title":"豊嶋正人活動概要報告書(PDFファイル:342KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_toyoshima.pdf","page":2,"text":"第1 次議会改革（平成8 年～平成14 年）\n○各会派、事務局から提案された65 件について、市議会議長会の「市議会の活性化方\n策」にしたがって分類し、会派代表者会議、議会運営委員会、議会機能に関する特別委\n員会において、調査・研究\n○主な実施事項\n・一般質問の見直し\n・委員会での一問一答制の導入\n・議員の各種審議会参画の見直し\n・委員会の所管事務調査の活用（閉会中の継続調査を積極的に行うことを合意）\n・請願手続きの緩和など（請願者の押印の廃止(署名の場合のみ)）\n・会議規則、委員会条例の見直し（請願紹介議員への質疑など高山市議会の運営に合\nわせた見直し）\n・情報公開取扱い基準の制定など（インターネット・有線TV 同時中継、録画放送、委員\n会、本会議議事録ネット公開）\n（２）「議会改革等に関する特別委員会」の設置\n○全国各地で議会の在り方が問われている\n○定数・選挙区問題と全国的な議会批判を受け行動開始\n ⇒議会の在り方から議員定数までについて考える「議会改革に関する特別委員会」を\n2009 年12 月、36 人の議員全員で設置、3 つの分科会を設けて運営\n・第1 分科会：「基本理念と議員の活動原則」\n・第2 分科会：「議会機能」\n・第3 分科会：「議員定数と選挙区」\n ⇒「高山市議会のあるべき姿」、「高山市議会の基本理念」を定め、これらに基づいて調\n査研究を推進\n（３）議員定数の決定プロセス\n○議会改革等に関する特別委員会\n 特別委員会を設置後、約3 カ月かけて選挙区・議員定数について検討議論\n○第1 回市民意見交換会の開催\n   2010 年4 月～5 月にかけて市内19 カ所で全市一区定数24 人とする方針について説\n明。市民皆さんから頂いた意見を集約。\n○2010 年6 月定例会\n 次回選挙から全市一区定数24 人とすることを正式に決定\n（４）高山市議会基本条例の制定とその特徴\n   2009 年12 月、「議員全員で構成する議会改革に関する特別委員会」を設置し2011\n年3 月までに38 回の特別委員会(全体会)、89 回の分科会、連絡調整を行うために11 回\nの小委員会を開催し、議会改革について公開で議論するとともに、市民意見交換会など\nの新たな取り組みの施行を重ねてきた。こうした議会改革の集大成として「高山市議会基\n本条例」を、2011 年3 月定例会において全員一致で可決し、同年5 月1 日施行した。\n①実践を通じて策定した条例\n計画～試行～評価～制度化の流れで条例を組み立てた。また、条文の内容を確実に実\n行するために、関連する条例、規程、要綱等を合わせて整備した。\n試行した取り組みは市民意見交換会の開催、事業評価結果の点検、政策討論会の開催\n及び委員会による政策提言の実施などであり、新規に整備した条例、規程、要綱等は12\n本に上る。\n②議論する議会をつくる\nより良い市政づくりには、市民と議会、そして議員同士が積極的に対話し、議論を深める\nことが欠かせないとの認識に基づき、議員同士で行う政策討論会等の実施による議論を\n行う機会を大幅に拡充するとともに、議員間の自由討議、市長等への反問権の付与等に\nよって議論を深めるための手法も充実させた。\n③政策提言によって議会機能を強化～市の政策水準の向上\n○監視型議会を標榜\n 高山市議会では、組織的な政策提言を積極的に行うことを通じて強力な監視型議会を","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"15173fd400b3040f","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"activity","title":"豊嶋正人活動概要報告書(PDFファイル:342KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_toyoshima.pdf","page":3,"text":"目指すこととした。政策立案に重点を置いた議会活動を展開している議会も見られるが、\n予算編成権が市長に専属すること、執行部に比べ政策立案のためのスタッフが圧倒的\nに手薄であること、また、地域主権の進展等により、執行機関が独自に策定する政策の\n増加が見込まれること等から、現実的選択として政策立案ではなく政策提言を積極的に\n行うこととした。\n○内容の質の向上と高い政治的効果の付与\n・政策提言の内容に高い説得力を持たせるために、作成にあたっては、常任委員会の所\n管事務調査を活用することとし、加えて、常任委員会が市民意見交換会、議員研修会を\n自由に活用できるような仕組みを整えた。また、政策提言の際には、目的・背景・基本的\n方向財政の見通しの4 点を明らかにすることとし、更に、政策提言を行った事項について\nは執行状況をチェックすることを条例に規定し、責任の重さを自覚することとした。3 常任\n委員会ごとに、6～7 件の内財政問題も含めて1 年間議論し、2～3 件に絞り翌年度予算\nに反映させる。\n○議員基礎力の向上\nこの政策提言の取り組みは、行政に対し、政策の提言や立案を求めていくことによって、\n市の政策水準を向上させることを主たる目的としているが、一連の活動を通じて、議員の\n審査能力や調査能力等の基礎力を高めることも重要な目的としている。\n④委員会活動を中心とした政策形成サイクル\n委員会\n○調査研究及び行政との議論。執行部は事業評価シートを提出\n・政策課題を設定し調査研究・政策課題について行政と議論・政策課題について先進地\n視察・政策課題に関する事業の評価結果と予算決算の審査結果の点検・政策課題をテ\nーマに議員研修会・政策提言(案)の作成\n市民意見交換会\n○市民との議論\n・地域別と分野別で政策課題をテーマに議論・次の政策課題の情報収集\n政策討論会\n○議員全員での議論\n・各委員会の政策提言の内容について議員全員で討論・政策提言の合意形成\n ↓\n市長等\n○政策提言を踏まえた政策の改善・立案\n・政策の立案～決定～執行～評価～改善～立案という市の政策形成サイクルにおいて、\n議会は、決定・評価という部分を担っている。決定の前には「審議」、評価の後には改善・\n立案を行政に求める「政策提言」を行う。議会の政策提言は、継続的な業務改善活動を\n推進するマネジメント手法であるPDCA サイクルのAction(改善)を促し、高山市の政策水\n準を向上させる。\n この政策提言は、市政について分野ごとに専門的に調査研究を行う機関である委員会\nを中心に行い、市民意見交換会や議員研修会、政策討論会などの取組を通じて、政策\n提言の妥当性や説得力等を高める。\n⑤市民参加の多様な機会を確保～市民との議論\n○市民意見交換会\n                 議員が少なくなり地域の声が届きにくくなるとの不安に応えるべく、小学校区を単位と なくなり地域の声が届きにくくなるとの不安に応えるべく、小学校区を単位と\nした地域別の市民意見交換会を行うこととした。また、常任委員会の調査研究を深める\nため、各種団体等を対象とした分野別の市民意見交換会も開催することとした。これらの\n意見交換会は、いずれも政策提言に向けた活動の一環として位置づけ、「政策提言」とい\nう形で市民の声を市政に反映させることとした。\n ■地域別市民意見交換会\n  ・年1 回以上20 日以上で実施\n ・各委員会で調査研究中の政策課題を意見交換\n ・政策提言作成の一環\n ■分野別市民意見交換会","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"15173fd400b3040f","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"activity","title":"豊嶋正人活動概要報告書(PDFファイル:342KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_toyoshima.pdf","page":4,"text":"・各委員会が企画して随時実施\n ・福祉、教育、産業、基盤整備など分野ごとに関係する各種団体等と意見交換\n ・政策提言作成の一環\n○請願及び陳情\n ・陳情等は政策提言作成のための情報源ととらえ、各常任委員会に振り分け調査研究\nに活用している。\n ・請願及び陳情の審議においては、必要に応じて提出者の意見を聞いたうえで審議・審\n査を行うこととしている。\n○情報公開\n 市民との議論の前提となる情報を共有するために、本会議、常任委員会(審査)、予算\n決算特別委員会及び政策討論会をCATV とインターネットで同時及び録画で中継してい\nる。また、委員会と会派の視察報告書、政務調査費の使途等を議会HP で公開している。\nさらに、議長が年5 回程度CATV に出演し、議会の活動状況を報告している。(グローカ\nルの評価で情報公開度No1)\n○議員研修会\n 議員研修会も政策提言に向けた活動の一環として位置づけ、各常任委員会の政策課\n題に関する内容で実施しているが、情報共有という観点からの市民の参加も可とし、講\n師や議員への質疑も認めている。\n⑥議決事件の追加条項を設け、市政に政策立案段階から関与する\n 地方分権の進展、基本構想の策定義務付けの廃止などを受け議会として自治体経営\nの根幹部分に積極的に関与していく必要性を痛感し、議決事件を追加する条項を設ける\nとともに、議決責任を果たすために、市長等に政策立案段階での報告を求めるものとし\nた。現時点では、総合計画の基本計画を位置付けている。\n⑦議員報酬に関する議案は、報酬等審議会の答申に基づくこと\n 議員報酬に関する議案は議員自ら提案していくとする議会も見られるが、当市議会で\nは、自分たちのことを自分たちで提案するのはお手盛りとみられても仕方がないこと、そ\nもそも議員報酬等について諮問を受ける立場にある報酬等審議会を活用することこそが\n基本であると考え、当該議案は、報酬等審議会の答申に基づいて市長が提案することを\n原則とした。なお、議会としても議員報酬の考え方や将来を見据えたあり方等については\n独自に調査研究を重ねることとしている。\n⑧年1 回、基本条例に基づいて議会活動を評価\n 当市議会では、少なくとも年 なくとも年1 回、議会基本条例に基づく活動の評価を、市民の意見も\n聴取しながら議会運営委員会を中心に実施することとした。\n（５）より深い審議・審査の実施～議決責任を果たすために\n 行政課題の複雑多様化や執行部独自に策定する政策の増加を見据え、より深く審議・\n審査することによって議決責任をしっかりと果すべく、議案の審議・審査方法等について\n見直しを図った。\n○事前協議の取止め(審査の形骸化の回避)\n ・委員会協議会を廃止\n ・閉会中の開催する委員会への議案情報の提供は受けない\n ・開会前の議案説明の際には質疑は行わない\n○議会審議と委員会審査の充実\n・質疑と一般質問の分離(目的：議案の内容や論点を明らかにする 質疑を審査に生かす\n委員会の活動期間を拡充する)\n・審査に関する取組の強化(内容：論点整理、現地調査・参考人招致、付帯決議の検討)\n・議員間討議の導入(運用：質疑が多数あり、論点が明確な案件について議長、委員長\nの判断で実施\n○委員会調査の充実\n・常任委員会の任期を1 年から2 年へ\n・閉会中の継続調査を積極的かつ計画的に実施するために、委員会を毎月定例開催と\nした。\n・委員会調査の最終目標を「政策提言」とすることで、活動の統一・シンプル化を図った","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"15173fd400b3040f","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"activity","title":"豊嶋正人活動概要報告書(PDFファイル:342KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_toyoshima.pdf","page":5,"text":"・委員会の会議運営は、議員間討議を中心に行っている\n○反問\n・行政との論点の活性化を図るべく、市長だけではなく行政側の全ての職員に反問権を\n付与した\n・質問の趣旨確認に止まらず、議会側の提出議案や政策提言に対しても行政側が反問\nできることとした 1 回のみ\n（６）平成25 年度の取り組み 総合計画の策定に向けて\n 平成25 年度から、高山市では、平成27 年度以降のまちづくりの方向性を示す、高山市\n第八次総合計画の策定作業に入った。\n 高山市議会では、条例で高山市総合計画における基本計画を議決事件としていること\nから、平成25 年5 月の臨時議会において、全議員を持って構成する「総合計画に関する\n特別委員会」を設置し、高山市第八次総合計画に関する調査・研究及び審査を行うことと\nした。\n 「総合計画に関する特別委員会」では、平成25 年度、各常任委員会を分科会と位置づ\nけ、分科会ごとに高山市第八次総合計画に向けての政策課題を設定したうえで、その政\n策課題について調査・研究を行ってきた。\n こうした調査・研究の結果を踏まえ、\n  ① 個性ある地域づくりの推進と更なる一体感の確保\n  ② 人口減社会における新たな行財政運営\n  ③ 健康・元気・安心社会の実現\n  ④ 観光まちづくりへの転換\n  ⑤ 都市施設(公共施設)整備の方向性\n  ⑥ 安全で安心して暮らせる社会の実現\n  ⑦ 環境と共生したまちづくり\nの７つを高山市第八次総合計画において取り組むべき政策課題として集約し、10 の政策\n提言として取りまとめ、市長に提案した。\n二元代表制の一翼を担う議事機関としての責務を果たすため、平成26 年度は、今後示\nされる計画案につて、政策提言の繁栄の検証など、審査・議決に向けた取組を進める。\n第八次総合計画に対する政策提言\n①．個性ある地域づくりの推進と更なる一体感の確保\n  政策提言1 地域づくり活動の促進に向けた仕組みづくり\n②．人口減社会における新たな行財政運営\n 政策提言２ 民間の力を活かした行政能力の集約化・効率化\n 政策提言３ 地域の実情に応じた柔軟な行政運営の推進\n 政策提言４ 限られた財源の有効活用と財源の確保\n③．健康・元気・安心社会の実現\n 政策提言５ 高齢者が生き生き暮らせる健康長寿社会の構築\n 政策提言６ 全ての子供が健やかに育つ環境の整備\n④．観光まちづくりへの転換\n 政策提言７ 観光まちづくりへの転換による産業力強化と雇用拡大\n⑤．都市施設(公共施設)整備の方向性\n 政策提言８ 公共施設の適正配置と整備\n⑥．安全で安心して暮らせる社会の実現\n 政策提言９ 災害に強いまちづくり\n⑦．環境と共生したまちづくり\n 政策提言１０ 自然環境を守り、活かすまちづくり\n（７）今後の取り組みについて～議会活動と議員活動の評価\n 第1 段階：議論の広場づくり～基本条例が求める議会と議員の「像」とは？\n 第２段階：相場の形成～議会と議員のあるべき姿\n 第３段階：議会評価制度の構築 政治倫理規程の制定\n(考 察)\n どこの自治体議会も、議会権限の適切な行使は当然のこととしながらも、いかに市民の","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"15173fd400b3040f","year":2014,"faction":"会派に属さない議員 豊嶋正人","kind":"activity","title":"豊嶋正人活動概要報告書(PDFファイル:342KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/h26_seimu_katudou_toyoshima.pdf","page":6,"text":"声を市政に反映させられるか、議会活動がいかに市民目線で行われているか、いかに市\n       民に身近で理解を深めてもらえるか、ということを大きな課題として取り組んでいる。\n       情報公開は当然のことであり、高山市議会が取り組んでいる開かれた議会、行動する議\n       会活動の取り組みに多くの事柄を学んだ。特に、常任委員会活動で政策提言の内容に\n       高い説得力、強力な政治的効果を持たせ、予算編成に反映させる取り組みは大事であ\n       る。市民要望の政策実現に大いに参考となった。\n\n\n       4-１．旧明宝村の職員から郡上市議会議員になっておられる清水議員と置田所長から、\n       熱く旧明宝村時代の村づくりにかけた想いと村民の力を活かして、村づくりに民間の感覚\n       とスピードをもって第三セクターを立ち上げ、特産品開発、温泉資源開発、スキー場開\n       発、道の駅販売施設などの整備を行い、年間150 万人の集客に成功し、小さな村である\n       けれども全国発信出来た誇りを学んだ。\n                                                                                           人口減少対策として都市住民の定住促進策、空き家活用などを中間支援組織のＮＰＯ 対策として都市住民の定住促進策、空き家活用などを中間支援組織のＮＰＯ\n       法人を都市からの移住者を中心に立ち上げ、イベント企画や地域情報誌発行などを積極\n       的に行っている。中でも「月刊めいほう」は、合併後のきめ細かな地域情報が無くなった\n       面を補うなど紙面内容が良い。今後は、現在の無料配布から発行経費問題などから買\n       取配付とするかどうか悩んでいるとの事。\n        4-2．明宝トマトケチャップ製造販売の株式会社明宝レディースを訪問し、3 代目社長であ\n       る鷲見社長から女性だけでの起業の苦労（主婦、母親、妻として事業化）、製品化家庭の\n       拘り（岐阜県産を原材料）、事業成功の要因（村・県の行政支援）、経営努力（販路拡大、\n       商品開発への熱意、他施設での飲食サービス）などの説明を受けた。県内産原材料の\n       確保問題や新商品開発への挑戦などの悩みを抱えつつ前向きな努力に好感が持てる。\n他会派との\n合同実施   ・清和会 ・会派に属さない議員\n\n                                            以 上","method":"pdf-text","status":"ok","manual_supplement":false}];
